// ========================= AUDIO SYNTHESIS ENGINE (CLEAN & POP-FREE) =========================
function getAudioContext() {
  if (!STATE.audioCtx) {
    const AudioCtx = window.AudioContext || window.webkitAudioContext;
    if (AudioCtx) STATE.audioCtx = new AudioCtx();
  }
  if (STATE.audioCtx && STATE.audioCtx.state === 'suspended') {
    STATE.audioCtx.resume();
  }
  return STATE.audioCtx;
}

const _lastSoundTimes = {};
let _lastAnySoundTime = 0;

function playSound(type) {
  if (!STATE.soundEnabled) return;
  
  // Rate-limiting cooldown to prevent audio stacking, distortion, or speaker pop
  const nowMs = performance.now();
  // Global cross-type cooldown: no two sounds of ANY type within limit
  if (nowMs - _lastAnySoundTime < (CONFIG.SOUND_GLOBAL_COOLDOWN_MS || 120)) return;
  // Per-type cooldown: same sound type must wait configured duration
  if (_lastSoundTimes[type] && (nowMs - _lastSoundTimes[type] < (CONFIG.SOUND_COOLDOWN_MS || 400))) return;
  _lastSoundTimes[type] = nowMs;
  _lastAnySoundTime = nowMs;

  try {
    const ctx = getAudioContext();
    if (!ctx) return;
    const now = ctx.currentTime;
    
    if (type === 'click') {
      const osc = ctx.createOscillator();
      const gain = ctx.createGain();
      osc.type = 'sine';
      osc.frequency.setValueAtTime(800, now);
      osc.frequency.exponentialRampToValueAtTime(400, now + 0.035);
      
      // Soft micro-attack (0.0001 -> 0.02) prevents DC click/pop
      gain.gain.setValueAtTime(0.0001, now);
      gain.gain.linearRampToValueAtTime(0.02, now + 0.006);
      gain.gain.exponentialRampToValueAtTime(0.0001, now + 0.035);
      
      osc.connect(gain);
      gain.connect(ctx.destination);
      osc.start(now);
      osc.stop(now + 0.04);
      osc.onended = () => {
        try { osc.disconnect(); gain.disconnect(); } catch (e) {}
      };
    } else if (type === 'chirp') {
      const osc = ctx.createOscillator();
      const gain = ctx.createGain();
      osc.type = 'sine'; // Sine waveform eliminates harmonic edge pops
      osc.frequency.setValueAtTime(1150, now);
      osc.frequency.linearRampToValueAtTime(1550, now + 0.06);
      
      // Smooth attack and release envelope
      gain.gain.setValueAtTime(0.0001, now);
      gain.gain.linearRampToValueAtTime(0.018, now + 0.008);
      gain.gain.exponentialRampToValueAtTime(0.0001, now + 0.065);
      
      osc.connect(gain);
      gain.connect(ctx.destination);
      osc.start(now);
      osc.stop(now + 0.07);
      osc.onended = () => {
        try { osc.disconnect(); gain.disconnect(); } catch (e) {}
      };
    } else if (type === 'lock') {
      [0, 0.06].forEach((delay, i) => {
        const osc = ctx.createOscillator();
        const gain = ctx.createGain();
        osc.type = 'sine';
        const startFreq = i === 0 ? 1350 : 1900;
        const endFreq = i === 0 ? 1650 : 2350;
        osc.frequency.setValueAtTime(startFreq, now + delay);
        osc.frequency.exponentialRampToValueAtTime(endFreq, now + delay + 0.04);
        
        gain.gain.setValueAtTime(0.0001, now + delay);
        gain.gain.linearRampToValueAtTime(0.02, now + delay + 0.006);
        gain.gain.exponentialRampToValueAtTime(0.0001, now + delay + 0.045);
        
        osc.connect(gain);
        gain.connect(ctx.destination);
        osc.start(now + delay);
        osc.stop(now + delay + 0.05);
        osc.onended = () => {
          try { osc.disconnect(); gain.disconnect(); } catch (e) {}
        };
      });
    } else if (type === 'alert') {
      [0, 0.12].forEach(delay => {
        const osc = ctx.createOscillator();
        const gain = ctx.createGain();
        osc.type = 'sine'; // Pure sine for clean non-abrasive alert
        osc.frequency.setValueAtTime(650, now + delay);
        osc.frequency.linearRampToValueAtTime(860, now + delay + 0.07);
        
        gain.gain.setValueAtTime(0.0001, now + delay);
        gain.gain.linearRampToValueAtTime(0.025, now + delay + 0.008);
        gain.gain.exponentialRampToValueAtTime(0.0001, now + delay + 0.08);
        
        osc.connect(gain);
        gain.connect(ctx.destination);
        osc.start(now + delay);
        osc.stop(now + delay + 0.09);
        osc.onended = () => {
          try { osc.disconnect(); gain.disconnect(); } catch (e) {}
        };
      });
    } else if (type === 'siren') {
      [0, 0.18].forEach((delay, i) => {
        const osc = ctx.createOscillator();
        const gain = ctx.createGain();
        osc.type = 'sine';
        osc.frequency.setValueAtTime(i === 0 ? 700 : 920, now + delay);
        
        gain.gain.setValueAtTime(0.0001, now + delay);
        gain.gain.linearRampToValueAtTime(0.022, now + delay + 0.01);
        gain.gain.exponentialRampToValueAtTime(0.0001, now + delay + 0.16);
        
        osc.connect(gain);
        gain.connect(ctx.destination);
        osc.start(now + delay);
        osc.stop(now + delay + 0.17);
        osc.onended = () => {
          try { osc.disconnect(); gain.disconnect(); } catch (e) {}
        };
      });
    }
  } catch (e) {
    // Audio context safely caught
  }
}

// ========================= TACTICAL TOAST & HOTLIST =========================
function showToast(title, msg, isAlert = false) {
  const toast = document.getElementById('tactical-toast');
  const tTitle = document.getElementById('toast-title');
  const tMsg = document.getElementById('toast-msg');
  if (!toast) return;
  tTitle.textContent = title;
  tMsg.textContent = msg;
  toast.classList.remove('hidden');
  if (isAlert) {
    playSound('alert');
  } else {
    playSound('chirp');
  }
  clearTimeout(window._toastTimer);
  window._toastTimer = setTimeout(() => {
    toast.classList.add('hidden');
  }, 6000);
}

