function downloadCertificateJson() {
  const veh = VEHICLES.find(v => v.id === STATE.selectedVehicle) || VEHICLES[0];
  const manifest = {
    standard: "Bharatiya Sakshya Adhiniyam 2023 Section 63",
    timestamp: new Date().toISOString(),
    targetVehicle: veh,
    evidenceChain: veh.trajectory.map((t, idx) => ({
      sequence: idx + 1,
      camId: t.cam,
      camName: getCameraName(t.cam),
      isMobileBusDashcam: !!t.mobile,
      coordinates: { lat: t.lat, lng: t.lng },
      ocrConfidence: t.conf,
      sha256Hash: generateHash(`${veh.plate}-${t.cam}-${t.time}`)
    }))
  };
  const blob = new Blob([JSON.stringify(manifest, null, 2)], { type: 'application/json' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = `VESPER_EVIDENCE_${veh.plate.replace(/\s+/g, '_')}.json`;
  a.click();
  URL.revokeObjectURL(url);
}

function toggleFullscreen() {
  const btn = document.getElementById('btn-fullscreen-toggle');
  if (!document.fullscreenElement) {
    document.documentElement.requestFullscreen().catch(() => {});
    if (btn) btn.textContent = 'Exit Fullscreen';
  } else {
    document.exitFullscreen().catch(() => {});
    if (btn) btn.textContent = 'Fullscreen';
  }
}

