function updateSightingChainUI(veh) {
  if (!veh || !veh.trajectory) return;

  const fixedHits = veh.trajectory.filter(t => !t.mobile).length;
  const busHits = veh.trajectory.filter(t => t.mobile).length;
  const totalHits = veh.trajectory.length;
  const lastStep = veh.trajectory[veh.trajectory.length - 1];

  // 1. Target Acquisition Summary Card in GIS Sidebar
  const elPlate = document.getElementById('assc-plate');
  if (elPlate) elPlate.textContent = veh.plate;
  const elSensors = document.getElementById('assc-sensors');
  if (elSensors) elSensors.textContent = `${fixedHits} Fixed CCTV + ${busHits} DTC Buses`;
  const elLastGps = document.getElementById('assc-last-gps');
  if (elLastGps && lastStep) elLastGps.textContent = `${lastStep.lat.toFixed(5)}, ${lastStep.lng.toFixed(5)}`;
  const elCorridor = document.getElementById('assc-corridor');
  if (elCorridor) elCorridor.textContent = veh.corridorName || 'Metropolitan Delhi Corridor';
  const elBadge = document.getElementById('assc-badge');
  if (elBadge) elBadge.textContent = `${totalHits} HITS CONFIRMED`;

  // 2. In-Map Tactical Sighting HUD
  const elGschPlate = document.getElementById('gsch-plate-display');
  if (elGschPlate) elGschPlate.textContent = veh.plate;
  const elGschHits = document.getElementById('gsch-hits-count');
  if (elGschHits) elGschHits.textContent = `${totalHits} Captures Linked`;
  const elGschRatio = document.getElementById('gsch-sensor-ratio');
  if (elGschRatio) elGschRatio.textContent = `${fixedHits} Fixed / ${busHits} Mobile Bus`;
  const elGschCoords = document.getElementById('gsch-last-coords');
  if (elGschCoords && lastStep) elGschCoords.textContent = `${lastStep.lat.toFixed(5)}, ${lastStep.lng.toFixed(5)}`;
  const elGschStatus = document.getElementById('gsch-trajectory-status');
  if (elGschStatus) elGschStatus.textContent = 'Vector Interconnected';

  // 3. Sighting Chain Dossier Modal Content
  const elModalPlate = document.getElementById('sc-modal-plate');
  if (elModalPlate) elModalPlate.textContent = veh.plate;
  const elModalDesc = document.getElementById('sc-modal-veh-desc');
  if (elModalDesc) elModalDesc.textContent = `${veh.color} ${veh.make || veh.type} · Re-ID Hash #${veh.reidHash || 'b4920fe1'}`;
  const elModalPill = document.getElementById('sc-modal-status-pill');
  if (elModalPill) {
    elModalPill.className = `sc-status-pill ${veh.isStolen ? 'stolen' : 'tracking'}`;
    elModalPill.textContent = veh.isStolen ? 'STOLEN ALERT (PURSUIT ACTIVE)' : `TRACKING (${totalHits} SIGHTINGS)`;
  }
  const elModalLastGps = document.getElementById('sc-modal-last-gps');
  if (elModalLastGps && lastStep) elModalLastGps.textContent = `${lastStep.lat.toFixed(5)}, ${lastStep.lng.toFixed(5)}`;
  const elModalRadius = document.getElementById('sc-modal-radius');
  if (elModalRadius) elModalRadius.textContent = `~${(0.8 + totalHits * 0.4).toFixed(1)} km (Corridor speed limit 50 km/h)`;
  const elModalDescText = document.getElementById('sc-modal-corridor-desc');
  if (elModalDescText && lastStep) {
    elModalDescText.innerHTML = `Target vehicle was last confirmed by <strong>${lastStep.cam} (${lastStep.street})</strong>. Target does NOT emit GPS coordinates. Sighting chronology interconnects road segments with projected unmonitored blind corridor downstream towards ${veh.corridorName}.`;
  }

  // Populate Chronological Sighting Table
  const tbody = document.getElementById('sc-modal-tbody');
  if (tbody) {
    let html = '';
    veh.trajectory.forEach((step, idx) => {
      const isLast = idx === veh.trajectory.length - 1;
      const timeStr = `+${step.time} min (${(10 + Math.floor(step.time / 60))}:${String(step.time % 60).padStart(2, '0')} AM)`;
      const speedStr = `${Math.round(32 + Math.sin(idx) * 12)} km/h`;
      const ocrStr = `${(step.conf * 100).toFixed(1)}%`;
      html += `
        <tr class="${isLast ? 'last-sighting' : ''}">
          <td style="font-weight:900;color:var(--accent-cyan)">#0${idx + 1}</td>
          <td>
            <span class="sc-sensor-tag ${step.mobile ? 'bus' : 'fixed'}">
              ${step.mobile ? 'DTC Mobile Bus' : 'Fixed CCTV ANPR'}
            </span>
            <div style="font-size:9px;color:#94a3b8;margin-top:2px">${step.cam}</div>
          </td>
          <td>
            <div style="font-weight:700;color:#fff">${step.street}</div>
            <div style="font-size:9px;color:#64748b">Sensor Node Coordinates Verified</div>
          </td>
          <td>
            <span class="sc-gps-coord">${step.lat.toFixed(5)}, ${step.lng.toFixed(5)}</span>
          </td>
          <td>${timeStr}</td>
          <td style="color:#34d399;font-weight:700">${speedStr}</td>
          <td style="color:var(--accent-cyan);font-weight:800">${ocrStr}</td>
          <td>
            <button class="sc-fly-btn" onclick="flyToSightingGPS(${step.lat}, ${step.lng}, '${step.cam}')">
              View GPS
            </button>
          </td>
        </tr>
      `;
    });
    tbody.innerHTML = html;
  }
}

function searchAndReconstructTrajectory(rawPlate, options = {}) {
  if (!rawPlate || !rawPlate.trim()) return;
  const rawClean = rawPlate.trim().toUpperCase();
  const cleanInput = rawClean.replace(/\s+/g, '');

  // 1. Check if vehicle exists (exact match or partial matching like '4921' or 'DL 1C')
  let veh = VEHICLES.find(v => {
    const vPlate = v.plate.replace(/\s+/g, '');
    return vPlate === cleanInput || vPlate.includes(cleanInput) || cleanInput.includes(vPlate);
  });

  if (!veh) {
    // 2. Check hotlist match (exact or partial)
    const hotMatch = HOTLIST.find(h => {
      const hPlate = h.plate.replace(/\s+/g, '');
      return hPlate === cleanInput || hPlate.includes(cleanInput) || cleanInput.includes(hPlate);
    });
    const isStolen = !!hotMatch;
    const newId = `VEH-${Date.now().toString().slice(-4)}`;

    // Realistic Delhi corridor template
    const templates = [
      {
        corridorName: 'Pusa Road - Connaught Place - ITO - Pragati Maidan Corridor',
        cams: [
          { cam:'CAM-JNC-04', time:0, lat:28.65136, lng:77.19067, conf:0.97, street:'Pusa Road Crossing (Karol Bagh)', pathIdx:0 },
          { cam:'BUS-DTC-419', time:4, lat:28.63706, lng:77.21005, conf:0.84, mobile:true, street:'Panchkuian Marg (Mobile Intercept)', pathIdx:124 },
          { cam:'CAM-JNC-01', time:7, lat:28.63150, lng:77.21672, conf:0.96, street:'Connaught Place Outer Circle', pathIdx:225 },
          { cam:'BUS-DTC-102', time:11, lat:28.62788, lng:77.24369, conf:0.91, mobile:true, street:'ITO Flyover / Vikas Marg', pathIdx:331 },
          { cam:'CAM-JNC-10', time:16, lat:28.61545, lng:77.24843, conf:0.94, street:'Pragati Maidan / Mathura Rd', pathIdx:396 }
        ],
        roadPath: VEHICLES[0].roadPath
      },
      {
        corridorName: 'AIIMS Flyover - Ring Road - Moolchand - Lajpat Nagar - Nehru Place',
        cams: [
          { cam:'CAM-JNC-05', time:0, lat:28.56544, lng:77.21015, conf:0.95, street:'AIIMS Flyover', pathIdx:0 },
          { cam:'BUS-DTC-522', time:3, lat:28.57093, lng:77.23908, conf:0.88, mobile:true, street:'Moolchand Metro Corridor', pathIdx:137 },
          { cam:'CAM-JNC-08', time:6, lat:28.57004, lng:77.24220, conf:0.94, street:'Lajpat Nagar Flyover', pathIdx:162 },
          { cam:'CAM-JNC-07', time:10, lat:28.54921, lng:77.25270, conf:0.92, street:'Nehru Place Outer Ring', pathIdx:280 }
        ],
        roadPath: VEHICLES[1].roadPath
      },
      {
        corridorName: 'Dhaula Kuan Interchange - Sardar Patel Marg - Teen Murti - India Gate',
        cams: [
          { cam:'CAM-JNC-09', time:0, lat:28.59216, lng:77.16162, conf:0.93, street:'Dhaula Kuan Junction', pathIdx:0 },
          { cam:'BUS-DTC-764', time:5, lat:28.60513, lng:77.19810, conf:0.82, mobile:true, street:'Panchsheel Marg Corridor', pathIdx:155 },
          { cam:'CAM-JNC-11', time:9, lat:28.61296, lng:77.22766, conf:0.89, street:'India Gate Circle', pathIdx:318 }
        ],
        roadPath: VEHICLES[2].roadPath
      }
    ];

    const tpl = isStolen ? templates[1] : templates[Math.floor(Math.random() * templates.length)];
    const types = ['Sedan', 'SUV', 'Hatchback'];
    const colors = ['White', 'Silver', 'Black', 'Grey', 'Red'];
    const makes = ['Maruti Swift Dzire', 'Toyota Fortuner', 'Hyundai i20', 'Honda City', 'Tata Nexon'];

    veh = {
      id: newId,
      plate: rawClean.includes(' ') ? rawClean : `DL ${rawClean.slice(0, 2)} ${rawClean.slice(2, 4)} ${rawClean.slice(4) || '9911'}`.trim(),
      type: isStolen ? 'SUV' : types[Math.floor(Math.random() * types.length)],
      color: isStolen ? 'Black' : colors[Math.floor(Math.random() * colors.length)],
      make: isStolen ? 'Toyota Fortuner' : makes[Math.floor(Math.random() * makes.length)],
      status: 'tracking',
      isStolen: isStolen,
      reidHash: Math.random().toString(16).substring(2, 10),
      corridorName: tpl.corridorName,
      trajectory: JSON.parse(JSON.stringify(tpl.cams)),
      roadPath: [...tpl.roadPath]
    };

    VEHICLES.push(veh);
    initVehicleList('gis-vehicle-list');
  }

  // If NOT in 50:25:25 split mode, switch to GIS window so the operator sees the map immediately.
  // If IN split mode, keep split mode so the operator retains full simultaneous view!
  if (!document.body.classList.contains('mode-split5025')) {
    switchWindow('gis');
  }

  // Select vehicle and rebuild sighting chain
  selectVehicle(veh.id);
  playSound('lock');

  const fixedHits = veh.trajectory.filter(t => !t.mobile).length;
  const busHits = veh.trajectory.filter(t => t.mobile).length;

  showToast(
    veh.isStolen ? 'HOTLIST MATCH: MULTI-NODE ANPR LOCK' : 'ANPR SIGHTING CHAIN RECONSTRUCTED',
    `Plate ${veh.plate}: ${veh.trajectory.length} Sightings linked across ${fixedHits} Fixed CCTVs & ${busHits} DTC Mobile Bus cameras. Blind corridor estimated!`,
    veh.isStolen
  );

  // If requested, open modal
  if (options.openModal) {
    openSightingChainModal();
  }
}

function openSightingChainModal() {
  const modal = document.getElementById('modal-sighting-chain');
  if (modal) {
    const veh = VEHICLES.find(v => v.id === STATE.selectedVehicle) || VEHICLES[0];
    updateSightingChainUI(veh);
    modal.classList.remove('hidden');
    playSound('chirp');
  }
}

function closeSightingChainModal() {
  const modal = document.getElementById('modal-sighting-chain');
  if (modal) {
    modal.classList.add('hidden');
    playSound('click');
  }
}

function connectSightingsOnMap(vehId) {
  const veh = VEHICLES.find(v => v.id === (vehId || STATE.selectedVehicle)) || VEHICLES[0];
  switchWindow('gis');
  closeSightingChainModal();
  drawTrajectory(veh);
  playSound('lock');
  showToast(' SIGHTING CHAIN CONNECTED', `Linked ${veh.trajectory.length} discrete ANPR camera coordinates for plate ${veh.plate}.`);
}

function buildExpectedTrajectory(vehId) {
  const veh = VEHICLES.find(v => v.id === (vehId || STATE.selectedVehicle)) || VEHICLES[0];
  switchWindow('gis');
  closeSightingChainModal();
  drawTrajectory(veh);

  // Highlight downstream intercept node
  const lastStep = veh.trajectory[veh.trajectory.length - 1];
  if (lastStep && STATE.maps.gis) {
    STATE.maps.gis.flyTo([lastStep.lat, lastStep.lng], 14, { animate: true, duration: 1.2 });
  }
  playSound('chirp');
  showToast(' EXPECTED TRAJECTORY BUILT', `Projected downstream blind corridor along ${veh.corridorName}. Dynamic reachability cone active.`);
}

function replaySightingChronology(vehId) {
  const veh = VEHICLES.find(v => v.id === (vehId || STATE.selectedVehicle)) || VEHICLES[0];
  switchWindow('gis');
  closeSightingChainModal();

  let stepIdx = 0;
  showToast(' REPLAYING SIGHTING CHRONOLOGY', `Advancing through ${veh.trajectory.length} confirmed camera hits...`);

  function nextStep() {
    if (stepIdx < veh.trajectory.length) {
      activateTimelineStep(veh, stepIdx);
      const step = veh.trajectory[stepIdx];
      STATE.maps.gis?.panTo([step.lat, step.lng], { animate: true, duration: 0.8 });
      playSound('chirp');
      stepIdx++;
      setTimeout(nextStep, 1800);
    } else {
      showToast('[OK] CHRONOLOGY COMPLETE', 'Reached last confirmed sighting. Expected trajectory vector projected.');
    }
  }
  nextStep();
}

function flyToSightingGPS(lat, lng, camName) {
  closeSightingChainModal();
  switchWindow('gis');
  if (STATE.maps.gis) {
    STATE.maps.gis.flyTo([lat, lng], 16, { animate: true, duration: 1.0 });
    playSound('chirp');
    showToast(' CAMERA GPS POSITION', `Focused on ${camName} (GPS ${lat.toFixed(5)}, ${lng.toFixed(5)})`);
  }
}

