// ========================= WINDOW NAVIGATION =========================
function switchWindow(windowId) {
  STATE.activeWindow = windowId;
  playSound('click');

  // If in split mode and clicking ANY window tab, gracefully deactivate split mode so the chosen window is 100% accessible
  if (document.body.classList.contains('mode-split5025')) {
    document.body.classList.remove('mode-split5025');
    document.querySelectorAll('.layout-btn').forEach(b => {
      b.classList.toggle('active', b.dataset.layout === 'tabs');
    });
    collapseExpandedPane();
  } else {
    collapseExpandedPane();
  }

  // Update nav tabs
  document.querySelectorAll('.nav-tab').forEach(t => t.classList.remove('active'));
  const tab = document.querySelector(`.nav-tab[data-window="${windowId}"]`);
  if (tab) tab.classList.add('active');

  // Update window panels
  document.querySelectorAll('.window-panel').forEach(p => p.classList.remove('active'));
  const panel = document.getElementById(`window-${windowId}`);
  if (panel) panel.classList.add('active');

  // Lazy initialize maps and content
  setTimeout(() => {
    if (windowId === 'surveillance' && !STATE.mapsInitialized.surv) {
      initSurvMap();
      STATE.mapsInitialized.surv = true;
    }
    if (windowId === 'gis' && STATE.maps.gis) {
      STATE.maps.gis.invalidateSize();
    }
    if (windowId === 'surveillance' && STATE.maps.surv) {
      STATE.maps.surv.invalidateSize();
    }
    if (windowId === 'dossier') {
      renderDossier();
    }
    if (windowId === 'ps124') {
      startPS124Simulation();
      if (typeof initUrbanTrafficAnalytics === 'function') initUrbanTrafficAnalytics();
  initSightingChainInteractions();
    }
    if (windowId === 'grid' && !STATE.mapsInitialized.grid) {
      initGridMap();
      STATE.mapsInitialized.grid = true;
    }
    if (windowId === 'grid' && STATE.maps.grid) {
      STATE.maps.grid.invalidateSize();
    }
  }, 100);
}

