// ========================= GIS MAP (WINDOW 3 — ROCK-SOLID & STABLE) =========================
const INDIA_BOUNDS = L.latLngBounds([[6.0, 68.0], [38.0, 98.0]]);

function initGISMap() {
  const map = L.map('gis-map', {
    center: CONFIG.MAP_CENTER,
    zoom: CONFIG.MAP_ZOOM,
    minZoom: 4,
    maxZoom: 19,
    maxBounds: INDIA_BOUNDS,
    maxBoundsViscosity: 1.0,
    zoomControl: true,
    attributionControl: false,
    zoomAnimation: true,
    fadeAnimation: true,
    markerZoomAnimation: true,
    inertia: true
  });

  const darkLayer = L.tileLayer('https://{s}.basemaps.cartocdn.com/dark_all/{z}/{x}/{y}{r}.png', {
    subdomains: 'abcd', maxZoom: 19, updateWhenIdle: true, keepBuffer: 2
  }).addTo(map);

  const satLayer = L.tileLayer('https://server.arcgisonline.com/ArcGIS/rest/services/World_Imagery/MapServer/tile/{z}/{y}/{x}', {
    maxZoom: 18, updateWhenIdle: true, keepBuffer: 2
  });

  // Road/label overlay for satellite mode — ensures roads align correctly
  // Uses CartoDB dark labels which render vector roads, place names, and boundaries
  // on a transparent layer that sits perfectly atop satellite imagery
  const roadOverlay = L.layerGroup([
    L.tileLayer('https://{s}.basemaps.cartocdn.com/dark_only_labels/{z}/{x}/{y}{r}.png', {
      subdomains: 'abcd', maxZoom: 19, opacity: 0.9, updateWhenIdle: true, keepBuffer: 2
    }),
    // Voyager semi-transparent road network for clearer road lines
    L.tileLayer('https://{s}.basemaps.cartocdn.com/rastertiles/voyager_nolabels/{z}/{x}/{y}{r}.png', {
      subdomains: 'abcd', maxZoom: 19, opacity: 0.25, updateWhenIdle: true, keepBuffer: 2
    })
  ]);

  const streetLayer = L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', {
    maxZoom: 19, updateWhenIdle: true, keepBuffer: 2
  });

  STATE.tileLayers = { dark: darkLayer, satellite: satLayer, street: streetLayer, roadOverlay: roadOverlay };
  STATE.currentTileLayer = 'dark';
  STATE.maps.gis = map;
  STATE.mapsInitialized.gis = true;

  // When user interacts with the map, pause auto-follow so map doesn't fight the user!
  map.on('dragstart zoomstart', () => {
    STATE.autoFollow = false;
    updateFollowButton();
  });

  initFixedCameras(map);
  initBuses(map);
  initGISTimelineControls();

  // Update stats
  const elFixed = document.getElementById('gis-fixed');
  if (elFixed) elFixed.textContent = FIXED_CAMERAS.length;
  const elBuses = document.getElementById('gis-buses');
  if (elBuses) elBuses.textContent = BUS_ROUTES.length;
  const elNodes = document.getElementById('stat-nodes');
  if (elNodes) elNodes.textContent = FIXED_CAMERAS.length + BUS_ROUTES.length;
}

// ════════════ MAP CAMERA CONTROLS ════════════
function updateFollowButton() {
  const btn = document.getElementById('btn-map-follow');
  const txt = document.getElementById('map-follow-text');
  if (!btn || !txt) return;
  btn.classList.toggle('active', STATE.autoFollow);
  txt.textContent = STATE.autoFollow ? 'Camera: Lock Target' : 'Camera: Free Roam';
}

function toggleMapFollow() {
  STATE.autoFollow = !STATE.autoFollow;
  updateFollowButton();
  if (STATE.autoFollow) {
    const veh = VEHICLES.find(v => v.id === STATE.selectedVehicle);
    if (veh && STATE.maps.gis) {
      const stepIdx = STATE.currentTrajectoryStep[veh.id] || 0;
      const step = veh.trajectory[stepIdx];
      if (step) STATE.maps.gis.panTo([step.lat, step.lng], { animate: true, duration: 0.6 });
    }
  }
  playSound('click');
}


function fitIndiaBounds() {
  const map = STATE.maps.gis;
  if (!map) return;
  const INDIA_SUB = L.latLngBounds([[6.5, 68.0], [37.5, 97.5]]);
  map.fitBounds(INDIA_SUB, { padding: [20, 20], animate: true, duration: 0.8 });
  STATE.autoFollow = false;
  updateFollowButton();
  playSound('click');
  showToast(' INDIA BOUNDS LOCKED', 'Map viewport fitted strictly to Indian territory boundaries.');
}

function fitDelhiCorridor() {
  const map = STATE.maps.gis;
  if (!map) return;
  map.setView(CONFIG.MAP_CENTER, 13, { animate: true, duration: 0.8 });
  playSound('click');
  showToast(' DELHI NCT CORRIDOR', 'Centered on active Delhi arterial surveillance corridor.');
}

function fitCurrentRoute() {
  const veh = VEHICLES.find(v => v.id === STATE.selectedVehicle);
  if (!veh || !STATE.maps.gis) return;
  const points = veh.trajectory.map(t => [t.lat, t.lng]);
  const bounds = L.latLngBounds(points);
  STATE.maps.gis.fitBounds(bounds.pad(0.2), { animate: true, duration: 0.5 });
  STATE.autoFollow = false;
  updateFollowButton();
  playSound('click');
}

function cycleMapLayer() {
  const map = STATE.maps.gis;
  if (!map || !STATE.tileLayers) return;
  
  // Remove current base layer
  map.removeLayer(STATE.tileLayers[STATE.currentTileLayer]);
  // Always remove road overlay when cycling (it's only for satellite)
  if (map.hasLayer(STATE.tileLayers.roadOverlay)) {
    map.removeLayer(STATE.tileLayers.roadOverlay);
  }
  
  if (STATE.currentTileLayer === 'dark') {
    STATE.currentTileLayer = 'satellite';
    STATE.tileLayers.satellite.addTo(map);
    STATE.tileLayers.roadOverlay.addTo(map); // Add road labels on top of satellite
    const txt = document.getElementById('map-layer-text');
    if (txt) txt.textContent = 'Satellite + Roads';
  } else if (STATE.currentTileLayer === 'satellite') {
    STATE.currentTileLayer = 'street';
    STATE.tileLayers.street.addTo(map);
    const txt = document.getElementById('map-layer-text');
    if (txt) txt.textContent = 'Street Map';
  } else {
    STATE.currentTileLayer = 'dark';
    STATE.tileLayers.dark.addTo(map);
    const txt = document.getElementById('map-layer-text');
    if (txt) txt.textContent = 'Dark Basemap';
  }
  playSound('click');
}

// ════════════ GODSEYE MAPPING ENGINE (ON MAIN GIS MAP) ════════════
function toggleGodsEyeMapMode() {
  STATE.godsEyeMapMode = !STATE.godsEyeMapMode;
  const btn = document.getElementById('btn-godseye-mapmode');
  const lbl = document.getElementById('godseye-mode-label');
  const container = document.getElementById('gis-map-wrapper');
  const radarCanvas = document.getElementById('gis-radar-canvas');
  const map = STATE.maps.gis;

  if (STATE.godsEyeMapMode) {
    if (btn) btn.classList.add('active');
    if (lbl) lbl.textContent = 'GodsEye Recon: ON';
    if (container) container.classList.add('godseye-active');
    if (radarCanvas) radarCanvas.classList.remove('hidden');

    // Switch main map to satellite + road overlay hybrid for accurate road alignment
    if (map && STATE.tileLayers) {
      map.removeLayer(STATE.tileLayers[STATE.currentTileLayer]);
      // Remove any existing road overlay first
      if (map.hasLayer(STATE.tileLayers.roadOverlay)) {
        map.removeLayer(STATE.tileLayers.roadOverlay);
      }
      STATE.currentTileLayer = 'satellite';
      STATE.tileLayers.satellite.addTo(map);
      // Overlay dark vector road labels for accurate road alignment
      STATE.tileLayers.roadOverlay.addTo(map);
      const layerTxt = document.getElementById('map-layer-text');
      if (layerTxt) layerTxt.textContent = 'GodsEye Recon';
    }

    // Render 30° directional optical FOV cones for all 12 fixed cameras
    drawGISCameraFOVCones();

    // Start rotating tactical radar sweep on map
    startGISRadarSweep();

    // Update HUD with tactical reconnaissance telemetry
    const protoVal = document.getElementById('gis-proto-val');
    if (protoVal) protoVal.textContent = 'GODSEYE RECON ACTIVE - LEO 462km';
    const coneVal = document.getElementById('gis-cone-val');
    if (coneVal) coneVal.textContent = 'GSD 0.3m/px · 2.4 Gbps Downlink';

    showToast('GODSEYE MAPPING ACTIVE', 'Satellite imagery with vector road overlay — roads now align with map coordinates.');
    playSound('alert');
  } else {
    if (btn) btn.classList.remove('active');
    if (lbl) lbl.textContent = 'GodsEye Recon: OFF';
    if (container) container.classList.remove('godseye-active');
    if (radarCanvas) radarCanvas.classList.add('hidden');

    if (STATE.gisRadarAF) cancelAnimationFrame(STATE.gisRadarAF);
    clearGISCameraFOVCones();

    // Revert to dark basemap
    if (map && STATE.tileLayers) {
      map.removeLayer(STATE.tileLayers[STATE.currentTileLayer]);
      // Remove road overlay
      if (map.hasLayer(STATE.tileLayers.roadOverlay)) {
        map.removeLayer(STATE.tileLayers.roadOverlay);
      }
      STATE.currentTileLayer = 'dark';
      STATE.tileLayers.dark.addTo(map);
      const layerTxt = document.getElementById('map-layer-text');
      if (layerTxt) layerTxt.textContent = 'Dark Basemap';
    }

    // Revert HUD
    const protoVal = document.getElementById('gis-proto-val');
    if (protoVal) protoVal.textContent = 'AIS-140 Opportunistic Relay';
    const coneVal = document.getElementById('gis-cone-val');
    if (coneVal) coneVal.textContent = 'r = 3.5 km | dt = 4 min';

    showToast(' STANDARD GIS MAPPING', 'Reverted to standard dark vector basemap.');
    playSound('click');
  }
}

function drawGISCameraFOVCones() {
  clearGISCameraFOVCones();
  const map = STATE.maps.gis;
  if (!map) return;

  FIXED_CAMERAS.forEach(cam => {
    const headingRad = (cam.heading - 90) * Math.PI / 180;
    const fovHalf = 15 * Math.PI / 180;
    const radius = 0.005; // ~500m
    const arcPoints = [[cam.lat, cam.lng]];
    for (let a = headingRad - fovHalf; a <= headingRad + fovHalf; a += 0.05) {
      arcPoints.push([cam.lat + Math.cos(a) * radius, cam.lng + Math.sin(a) * radius]);
    }
    arcPoints.push([cam.lat, cam.lng]);
    const arc = L.polygon(arcPoints, {
      color: '#00e5ff', fillColor: '#00e5ff', fillOpacity: 0.12, weight: 1.5, opacity: 0.6
    }).addTo(map);
    STATE.godsEyeCoverageArcs.push(arc);

    // Also draw a directional line for the camera heading
    const lineEnd = [
      cam.lat + Math.cos(headingRad) * radius * 1.3,
      cam.lng + Math.sin(headingRad) * radius * 1.3
    ];
    const headingLine = L.polyline([[cam.lat, cam.lng], lineEnd], {
      color: '#00e5ff', weight: 1, opacity: 0.4, dashArray: '4 4'
    }).addTo(map);
    STATE.godsEyeCoverageArcs.push(headingLine);
  });
}

function clearGISCameraFOVCones() {
  if (STATE.godsEyeCoverageArcs && STATE.maps.gis) {
    STATE.godsEyeCoverageArcs.forEach(arc => STATE.maps.gis.removeLayer(arc));
  }
  STATE.godsEyeCoverageArcs = [];
}

function startGISRadarSweep() {
  const canvas = document.getElementById('gis-radar-canvas');
  if (!canvas) return;

  // Build static ring buffer (offscreen, rendered once)
  let staticBuffer = null;
  function buildGISStaticBuffer(w, h) {
    const buf = document.createElement('canvas');
    buf.width = w; buf.height = h;
    const bctx = buf.getContext('2d');
    const cx = w / 2, cy = h / 2;
    const maxR = Math.min(w, h) * 0.44;
    // Concentric range rings
    [0.33, 0.66, 1.0].forEach(p => {
      bctx.strokeStyle = 'rgba(0, 229, 255, 0.08)';
      bctx.lineWidth = 0.5;
      bctx.setLineDash([3, 7]);
      bctx.beginPath();
      bctx.arc(cx, cy, maxR * p, 0, Math.PI * 2);
      bctx.stroke();
      bctx.setLineDash([]);
    });
    // Crosshairs
    bctx.strokeStyle = 'rgba(0,229,255,0.08)';
    bctx.lineWidth = 0.4;
    bctx.beginPath();
    bctx.moveTo(cx - maxR, cy); bctx.lineTo(cx + maxR, cy);
    bctx.moveTo(cx, cy - maxR); bctx.lineTo(cx, cy + maxR);
    bctx.stroke();
    return buf;
  }

  function resizeRadar() {
    canvas.width = canvas.offsetWidth;
    canvas.height = canvas.offsetHeight;
    staticBuffer = buildGISStaticBuffer(canvas.width, canvas.height);
  }
  resizeRadar();
  window.addEventListener('resize', resizeRadar);

  let angle = 0;
  let lastTime = performance.now();

  function draw(timestamp) {
    if (!STATE.godsEyeMapMode) return;

    // Skip rendering when tab is backgrounded (0% idle CPU)
    if (document.hidden) {
      STATE.gisRadarAF = requestAnimationFrame(draw);
      return;
    }

    // Delta-time for frame-rate-independent smooth rotation
    const dt = Math.min(0.05, (timestamp - lastTime) / 1000);
    lastTime = timestamp;
    angle = (angle + dt * 0.8) % (Math.PI * 2);

    const ctx = canvas.getContext('2d');
    const w = canvas.width, h = canvas.height;
    const cx = w / 2, cy = h / 2;
    const maxR = Math.min(w, h) * 0.44;

    // 1. Clear frame
    ctx.clearRect(0, 0, w, h);

    // 2. Blit pre-rendered static grid (single ultra-fast drawImage)
    if (staticBuffer) ctx.drawImage(staticBuffer, 0, 0);

    // 3. Dynamic rotating sweep cone
    const sweepWidth = 0.35;
    const grad = ctx.createConicGradient(angle, cx, cy);
    grad.addColorStop(0, 'transparent');
    grad.addColorStop(0.01, 'rgba(0, 229, 255, 0.08)');
    grad.addColorStop(sweepWidth / (Math.PI * 2), 'rgba(0, 229, 255, 0.02)');
    grad.addColorStop(sweepWidth / (Math.PI * 2) + 0.01, 'transparent');
    grad.addColorStop(1, 'transparent');

    ctx.fillStyle = grad;
    ctx.beginPath();
    ctx.arc(cx, cy, maxR, 0, Math.PI * 2);
    ctx.fill();

    // 4. Sweep leading edge line
    ctx.strokeStyle = 'rgba(0, 229, 255, 0.35)';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(cx, cy);
    ctx.lineTo(cx + Math.cos(angle) * maxR, cy + Math.sin(angle) * maxR);
    ctx.stroke();

    STATE.gisRadarAF = requestAnimationFrame(draw);
  }
  draw();
}

// ════════════ PRODUCTION API GATEWAY MANAGER ════════════
function setupApiKeyControls() {
  // Show / Hide key toggles
  document.querySelectorAll('.api-key-toggle-btn').forEach(btn => {
    btn.addEventListener('click', (e) => {
      e.stopPropagation();
      const targetId = btn.dataset.target;
      const input = document.getElementById(targetId);
      if (!input) return;
      if (input.type === 'password') {
        input.type = 'text';
        btn.textContent = '';
      } else {
        input.type = 'password';
        btn.textContent = '';
      }
      playSound('click');
    });
  });

  // Copy key buttons
  document.querySelectorAll('.api-key-copy-btn').forEach(btn => {
    btn.addEventListener('click', (e) => {
      e.stopPropagation();
      const targetId = btn.dataset.target;
      const input = document.getElementById(targetId);
      if (!input) return;
      navigator.clipboard.writeText(input.value).then(() => {
        showToast(' KEY COPIED', `API credential copied to clipboard.`);
        btn.textContent = '[OK]';
        setTimeout(() => { btn.textContent = ''; }, 1500);
        playSound('chirp');
      }).catch(() => {
        input.select();
        document.execCommand('copy');
        showToast(' KEY COPIED', `API credential copied to clipboard.`);
      });
    });
  });

  // Individual test ping buttons
  document.querySelectorAll('.api-test-btn').forEach(btn => {
    btn.addEventListener('click', (e) => {
      e.stopPropagation();
      const apiName = btn.dataset.api;
      callSingleAPI(apiName);
    });
  });

  // Call & Authenticate All
  document.getElementById('btn-api-test-all')?.addEventListener('click', authenticateAllAPIs);
  document.getElementById('btn-fire-all-apis')?.addEventListener('click', authenticateAllAPIs);
  document.getElementById('btn-hero-call-apis')?.addEventListener('click', authenticateAllAPIs);
  document.getElementById('btn-hero-open-api-modal')?.addEventListener('click', () => {
    document.getElementById('modal-api-gateway')?.classList.remove('hidden');
    authenticateAllAPIs();
    playSound('chirp');
  });

  // Terminal actions
  document.getElementById('btn-clear-api-log')?.addEventListener('click', () => {
    const log = document.getElementById('api-terminal-log');
    if (log) log.innerHTML = '';
    showToast(' LOG CLEARED', 'API network stream log cleared.');
  });
  document.getElementById('btn-export-api-log')?.addEventListener('click', exportApiAuditLog);
}

