function initGodsEye() {
  if (GODSEYE.initialized) return;

  GODSEYE.cacheDOM();

  // Create map with optimized rendering settings
  const map = L.map('godseye-map', {
    center: CONFIG.MAP_CENTER,
    zoom: 15,
    minZoom: 4,
    maxZoom: 19,
    maxBounds: INDIA_BOUNDS,
    maxBoundsViscosity: 1.0,
    zoomControl: false,
    attributionControl: false,
    fadeAnimation: true,
    markerZoomAnimation: true,
    preferCanvas: true
  });

  // 1. High-Resolution Satellite Basemap (Esri World Imagery)
  L.tileLayer('https://server.arcgisonline.com/ArcGIS/rest/services/World_Imagery/MapServer/tile/{z}/{y}/{x}', {
    maxZoom: 19,
    updateWhenIdle: true,
    keepBuffer: 2
  }).addTo(map);

  // 2. High-Contrast Dark Street & Road Labels Overlay
  L.tileLayer('https://{s}.basemaps.cartocdn.com/dark_only_labels/{z}/{x}/{y}{r}.png', {
    subdomains: 'abcd',
    maxZoom: 19,
    opacity: 0.95,
    updateWhenIdle: true,
    keepBuffer: 2
  }).addTo(map);

  GODSEYE.map = map;

  // Add fixed camera markers with FOV viewing cones
  FIXED_CAMERAS.forEach(cam => {
    const icon = L.divIcon({ className: 'ge-marker-cam', iconSize: [12, 12], iconAnchor: [6, 6] });
    const marker = L.marker([cam.lat, cam.lng], { icon }).addTo(map);
    marker.bindPopup(`<div style="padding:3px;background:#0a0e17;color:#00e5ff;font-size:10px;font-weight:700">${cam.id}<br><span style="color:#94a3b8;font-size:9px">${cam.name}</span><br><span style="color:#34d399;font-size:8px">Click to inspect feed</span></div>`, { className: 'ge-popup' });
    marker.on('click', () => GODSEYE.openSensorPiP(cam));
    GODSEYE.markers.cameras.push(marker);

    // 30° viewing cone, 500m radius
    const headingRad = (cam.heading - 90) * Math.PI / 180;
    const fovHalf = 15 * Math.PI / 180;
    const radius = 0.0045; // ~500m
    const arcPoints = [[cam.lat, cam.lng]];
    for (let a = headingRad - fovHalf; a <= headingRad + fovHalf; a += 0.08) {
      arcPoints.push([cam.lat + Math.cos(a) * radius, cam.lng + Math.sin(a) * radius]);
    }
    arcPoints.push([cam.lat, cam.lng]);
    const arc = L.polygon(arcPoints, {
      color: '#00e5ff', fillColor: '#00e5ff', fillOpacity: 0.07, weight: 1, opacity: 0.35
    }).addTo(map);
    GODSEYE.markers.coverageArcs.push(arc);
  });

  // Add mobile bus markers
  BUS_ROUTES.forEach(bus => {
    const icon = L.divIcon({ className: 'ge-marker-bus', iconSize: [12, 12], iconAnchor: [6, 6] });
    const wp = STATE.busPositions[bus.id] || bus.waypoints[0];
    const marker = L.marker([wp.lat, wp.lng], { icon }).addTo(map);
    marker.bindPopup(`<div style="padding:3px;background:#0a0e17;color:#fbbf24;font-size:10px;font-weight:700">${bus.id}<br><span style="color:#94a3b8;font-size:9px">${bus.name}</span><br><span style="color:#34d399;font-size:8px">Click to inspect feed</span></div>`, { className: 'ge-popup' });
    marker.on('click', () => GODSEYE.openSensorPiP({ id: bus.id, name: bus.name, lat: wp.lat, lng: wp.lng, heading: 90 }));
    GODSEYE.markers.buses.push({ id: bus.id, marker });
  });

  // Initialize Line-of-Sight dynamic beam
  GODSEYE.losBeam = L.polyline([], {
    color: '#00e5ff',
    weight: 2,
    opacity: 0.85,
    dashArray: '6 6',
    lineCap: 'round'
  }).addTo(map);

  // Wire Top Banner Controls
  wireGodsEyeControls();

  GODSEYE.initialized = true;
}

function wireGodsEyeControls() {
  // Altitude zoom presets
  document.getElementById('ge-alt-leo')?.addEventListener('click', () => GODSEYE.setAltitudeMode('leo'));
  document.getElementById('ge-alt-tactical')?.addEventListener('click', () => GODSEYE.setAltitudeMode('tactical'));
  document.getElementById('ge-alt-lock')?.addEventListener('click', () => GODSEYE.setAltitudeMode('lock'));

  // Tactical toggles
  document.getElementById('ge-toggle-los')?.addEventListener('click', function() {
    GODSEYE.losEnabled = !GODSEYE.losEnabled;
    this.classList.toggle('active', GODSEYE.losEnabled);
    if (!GODSEYE.losEnabled && GODSEYE.losBeam && GODSEYE.map) {
      GODSEYE.losBeam.setLatLngs([]);
    }
    playSound('click');
  });

  document.getElementById('ge-toggle-flir')?.addEventListener('click', function() {
    GODSEYE.flirMode = !GODSEYE.flirMode;
    this.classList.toggle('active', GODSEYE.flirMode);
    if (GODSEYE.dom.mapContainer) {
      GODSEYE.dom.mapContainer.classList.toggle('flir-active', GODSEYE.flirMode);
    }
    playSound('alert');
  });

  document.getElementById('ge-toggle-interceptions')?.addEventListener('click', function() {
    GODSEYE.interceptionsEnabled = !GODSEYE.interceptionsEnabled;
    this.classList.toggle('active', GODSEYE.interceptionsEnabled);
    GODSEYE.markers.intercepts.forEach(m => {
      if (GODSEYE.interceptionsEnabled) {
        m.addTo(GODSEYE.map);
      } else {
        GODSEYE.map.removeLayer(m);
      }
    });
    playSound('click');
  });

  // Interception Authorization Directive
  document.getElementById('btn-ge-dispatch-intercept')?.addEventListener('click', () => {
    GODSEYE.authorizeInterception();
  });

  // Sensor PiP Controls
  document.getElementById('btn-ge-pip-close')?.addEventListener('click', () => {
    document.getElementById('ge-sensor-pip')?.classList.add('hidden');
    playSound('click');
  });

  document.getElementById('btn-ge-pip-switch')?.addEventListener('click', () => {
    closeGodsEye();
    switchWindow('surveillance');
  });
}

// ════════════ LIVE SENSOR PIP PREVIEW IN GODSEYE ════════════
GODSEYE.openSensorPiP = function(node) {
  const pip = document.getElementById('ge-sensor-pip');
  if (!pip) return;
  pip.classList.remove('hidden');

  const title = document.getElementById('ge-pip-title');
  const loc = document.getElementById('ge-pip-location');
  const plate = document.getElementById('ge-pip-plate');
  if (title) title.textContent = `LIVE SENSOR // ${node.id}`;
  if (loc) loc.textContent = `${node.name || 'Mobile Transit Node'} · ${node.lat.toFixed(4)}°N, ${node.lng.toFixed(4)}°E`;
  if (plate) {
    const veh = VEHICLES.find(v => v.id === STATE.selectedVehicle) || VEHICLES[0];
    plate.textContent = `${veh.plate} (${veh.isStolen ? ' STOLEN' : 'TRACKED'})`;
  }

  // Draw simulated live optical stream frame
  const canvas = document.getElementById('ge-pip-canvas');
  if (canvas) {
    const ctx = canvas.getContext('2d');
    const w = canvas.width, h = canvas.height;
    ctx.fillStyle = '#060a14';
    ctx.fillRect(0, 0, w, h);

    // Street perspective
    ctx.strokeStyle = 'rgba(0, 229, 255, 0.22)';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(w * 0.15, h); ctx.lineTo(w * 0.45, h * 0.4);
    ctx.moveTo(w * 0.85, h); ctx.lineTo(w * 0.55, h * 0.4);
    ctx.stroke();

    // Road markings
    ctx.strokeStyle = 'rgba(251, 191, 36, 0.4)';
    ctx.setLineDash([8, 10]);
    ctx.beginPath();
    ctx.moveTo(w * 0.5, h); ctx.lineTo(w * 0.5, h * 0.4);
    ctx.stroke();
    ctx.setLineDash([]);

    // Detected suspect vehicle box
    const bx = w * 0.35, by = h * 0.45, bw = 84, bh = 54;
    ctx.strokeStyle = '#00e5ff';
    ctx.lineWidth = 1.5;
    ctx.strokeRect(bx, by, bw, bh);

    // YOLO tag
    ctx.fillStyle = 'rgba(0, 229, 255, 0.9)';
    ctx.fillRect(bx, by - 13, 76, 13);
    ctx.fillStyle = '#0a0e17';
    ctx.font = 'bold 8px monospace';
    ctx.fillText('YOLOv8 98.4%', bx + 4, by - 3);

    // License Plate tag
    ctx.fillStyle = '#ffffff';
    ctx.fillRect(bx + 14, by + bh - 15, 56, 13);
    ctx.fillStyle = '#0f172a';
    ctx.font = 'bold 7.5px monospace';
    const veh = VEHICLES.find(v => v.id === STATE.selectedVehicle) || VEHICLES[0];
    ctx.fillText(veh.plate, bx + 17, by + bh - 5);
  }

  playSound('chirp');
};

// ════════════ TACTICAL ROADBLOCK & PERIMETER SEAL DIRECTIVE ════════════
GODSEYE.authorizeInterception = function(chokePoint) {
  const primary = chokePoint || GODSEYE.primaryChokePoint || GODSEYE.chokePoints[0];
  if (!primary || !GODSEYE.map) return;

  // Clear previous blockade layers if any
  if (GODSEYE.blockadeMarker) GODSEYE.map.removeLayer(GODSEYE.blockadeMarker);
  if (GODSEYE.blockadeVector) GODSEYE.map.removeLayer(GODSEYE.blockadeVector);

  // Roadblock Circle
  GODSEYE.blockadeMarker = L.circle([primary.lat, primary.lng], {
    radius: 120,
    color: '#ef4444',
    fillColor: '#ef4444',
    fillOpacity: 0.28,
    weight: 2,
    dashArray: '5 5'
  }).addTo(GODSEYE.map);

  // Dispatch vector from nearest police unit
  const unitLat = primary.lat + 0.005;
  const unitLng = primary.lng - 0.006;
  GODSEYE.blockadeVector = L.polyline([[unitLat, unitLng], [primary.lat, primary.lng]], {
    color: '#34d399',
    weight: 3,
    dashArray: '6 6'
  }).addTo(GODSEYE.map);

  const btn = document.getElementById('btn-ge-dispatch-intercept');
  if (btn) {
    btn.classList.add('armed');
    btn.innerHTML = `[CONFIRMED] ROADBLOCK DEPLOYED · ${primary.unit.toUpperCase()} ARMED`;
  }

  const statusText = document.getElementById('ge-status-text');
  if (statusText) statusText.textContent = `CORDON ARMED · ${primary.name.toUpperCase()}`;

  showToast(' TACTICAL INTERCEPTION AUTHORIZED', `${primary.unit} deployed with spike-strip cordon at ${primary.name}. Corridor exit sealed.`);
  playSound('alert');
};

GODSEYE.setAltitudeMode = function(mode) {
  GODSEYE.altitudeMode = mode;
  document.querySelectorAll('.ge-alt-btn').forEach(b => b.classList.remove('active'));
  document.getElementById(`ge-alt-${mode}`)?.classList.add('active');

  const veh = VEHICLES.find(v => v.id === STATE.selectedVehicle) || VEHICLES[0];
  const stepIdx = STATE.currentTrajectoryStep[veh.id] || 0;
  const step = veh.trajectory[stepIdx];
  const vehMarker = STATE.markers.vehicles[veh.id];
  const pos = vehMarker ? vehMarker.getLatLng() : [step.lat, step.lng];

  if (!GODSEYE.map) return;

  if (mode === 'leo') {
    GODSEYE.map.flyTo(pos, 13, { duration: 0.8 });
    if (GODSEYE.dom.altitude) GODSEYE.dom.altitude.textContent = 'ISRO Bhuvan 1.2m';
    if (GODSEYE.dom.swath) GODSEYE.dom.swath.textContent = '42.0 km';
    if (GODSEYE.dom.gsd) GODSEYE.dom.gsd.textContent = 'Hailo-8 INT8 (5W)';
  } else if (mode === 'tactical') {
    GODSEYE.map.flyTo(pos, 15, { duration: 0.8 });
    if (GODSEYE.dom.altitude) GODSEYE.dom.altitude.textContent = 'ISRO Bhuvan 0.3m';
    if (GODSEYE.dom.swath) GODSEYE.dom.swath.textContent = '18.5 km';
    if (GODSEYE.dom.gsd) GODSEYE.dom.gsd.textContent = 'Hailo-8 INT8 (5W)';
  } else if (mode === 'lock') {
    GODSEYE.map.flyTo(pos, 18, { duration: 0.8 });
    if (GODSEYE.dom.altitude) GODSEYE.dom.altitude.textContent = 'Orthomosaic 0.05m';
    if (GODSEYE.dom.swath) GODSEYE.dom.swath.textContent = '4.2 km';
    if (GODSEYE.dom.gsd) GODSEYE.dom.gsd.textContent = 'Hailo-8 INT8 (5W)';
  }
  playSound('click');
};

GODSEYE.renderTargetChips = function() {
  const container = GODSEYE.dom.targetChips || document.getElementById('ge-target-chips');
  if (!container) return;
  container.innerHTML = '';

  VEHICLES.forEach(veh => {
    const chip = document.createElement('div');
    const isSel = veh.id === STATE.selectedVehicle;
    chip.className = `ge-target-chip ${veh.isStolen ? 'stolen' : ''} ${isSel ? 'active' : ''}`;
    chip.innerHTML = `<span>${veh.isStolen ? '' : ''}</span> <span>${veh.plate}</span>`;
    chip.addEventListener('click', () => {
      GODSEYE.switchTarget(veh.id);
    });
    container.appendChild(chip);
  });
};

GODSEYE.switchTarget = function(vehicleId) {
  selectVehicle(vehicleId);
  GODSEYE.renderTargetChips();

  const veh = VEHICLES.find(v => v.id === vehicleId);
  if (!veh) return;

  const stepIdx = STATE.currentTrajectoryStep[veh.id] || 0;
  const step = veh.trajectory[stepIdx];
  const map = GODSEYE.map;

  if (map) {
    map.setView([step.lat, step.lng], GODSEYE.altitudeMode === 'lock' ? 18 : (GODSEYE.altitudeMode === 'leo' ? 13 : 15), { animate: true });

    // Update trajectory
    if (GODSEYE.markers.trajectory) map.removeLayer(GODSEYE.markers.trajectory);
    const points = (veh.roadPath || veh.trajectory).map(t => [t.lat, t.lng]);
    const geCasing = L.polyline(points, { color: '#00e5ff', weight: 7, opacity: 0.38, lineCap: 'round', lineJoin: 'round' });
    const geLine = L.polyline(points, { color: veh.isStolen ? '#f87171' : '#69f0ae', weight: 3.5, opacity: 0.95, dashArray: '8 6', lineCap: 'round', lineJoin: 'round' });
    GODSEYE.markers.trajectory = L.layerGroup([geCasing, geLine]).addTo(map);

    // Update target marker
    if (GODSEYE.markers.target) map.removeLayer(GODSEYE.markers.target);
    const targetIcon = L.divIcon({ className: 'ge-marker-target', iconSize: [22, 22], iconAnchor: [11, 11] });
    GODSEYE.markers.target = L.marker([step.lat, step.lng], { icon: targetIcon, zIndexOffset: 2000 }).addTo(map);
  }

  updateGodsEyePanels(veh, step, stepIdx);
  GODSEYE.updateInterceptionMatrix(veh, step);
  playSound('alert');
};

function openGodsEye() {
  initGodsEye();
  const overlay = GODSEYE.dom.overlay || document.getElementById('godseye-overlay');
  if (!overlay) return;
  overlay.classList.remove('hidden');
  GODSEYE.active = true;
  playSound('alert');

  const map = GODSEYE.map;
  setTimeout(() => map.invalidateSize(), 80);
  setTimeout(() => map.invalidateSize(), 250);

  // Render target switcher chips
  GODSEYE.renderTargetChips();

  // Get current vehicle
  const veh = VEHICLES.find(v => v.id === STATE.selectedVehicle) || VEHICLES[0];
  const stepIdx = STATE.currentTrajectoryStep[veh.id] || 0;
  const step = veh.trajectory[stepIdx];

  // Center map on target
  map.setView([step.lat, step.lng], 15, { animate: true });

  // Draw road-matched trajectory line
  if (GODSEYE.markers.trajectory) map.removeLayer(GODSEYE.markers.trajectory);
  const points = (veh.roadPath || veh.trajectory).map(t => [t.lat, t.lng]);
  const geCasing = L.polyline(points, { color: '#00e5ff', weight: 7, opacity: 0.38, lineCap: 'round', lineJoin: 'round' });
  const geLine = L.polyline(points, { color: veh.isStolen ? '#f87171' : '#69f0ae', weight: 3.5, opacity: 0.95, dashArray: '8 6', lineCap: 'round', lineJoin: 'round' });
  GODSEYE.markers.trajectory = L.layerGroup([geCasing, geLine]).addTo(map);

  // Target marker
  if (GODSEYE.markers.target) map.removeLayer(GODSEYE.markers.target);
  const targetIcon = L.divIcon({ className: 'ge-marker-target', iconSize: [22, 22], iconAnchor: [11, 11] });
  GODSEYE.markers.target = L.marker([step.lat, step.lng], { icon: targetIcon, zIndexOffset: 2000 }).addTo(map);
  GODSEYE.markers.target.bindPopup(`<div style="padding:4px;background:#0a0e17;color:#f87171;font-size:11px;font-weight:800">${veh.plate}<br><span style="color:#94a3b8;font-size:9px">${veh.make} · ${veh.color}</span>${veh.isStolen ? '<br><span style="color:#f87171"> STOLEN VEHICLE</span>' : ''}<br><span style="color:#00e5ff;font-size:8px;font-weight:700"> ${step.street || veh.corridorName}</span></div>`);

  // Telemetry panels
  updateGodsEyePanels(veh, step, stepIdx);

  // Build AI Interception Bottlenecks
  GODSEYE.updateInterceptionMatrix(veh, step);

  // Start double-buffered high-efficiency radar sweep
  startRadarSweep();

  // Start live updates (1000ms throttled)
  GODSEYE.updateInterval = setInterval(() => updateGodsEyeLive(), 1000);

  // Start clock
  GODSEYE.clockInterval = setInterval(() => {
    if (GODSEYE.dom.clock) {
      GODSEYE.dom.clock.textContent = new Date().toTimeString().split(' ')[0];
    }
  }, 1000);

  showToast(' GODSEYE ORBITAL VIEW ACTIVE', 'Satellite overhead surveillance mode with hardware-accelerated radar and AI intercept matrix.');
}

function closeGodsEye() {
  const overlay = GODSEYE.dom.overlay || document.getElementById('godseye-overlay');
  if (overlay) overlay.classList.add('hidden');
  GODSEYE.active = false;

  if (GODSEYE.radarAF) {
    cancelAnimationFrame(GODSEYE.radarAF);
    GODSEYE.radarAF = null;
  }
  if (GODSEYE.updateInterval) clearInterval(GODSEYE.updateInterval);
  if (GODSEYE.clockInterval) clearInterval(GODSEYE.clockInterval);

  if (GODSEYE.losBeam && GODSEYE.map) {
    GODSEYE.losBeam.setLatLngs([]);
  }

  playSound('click');
}

GODSEYE.updateInterceptionMatrix = function(veh, pos) {
  const listContainer = GODSEYE.dom.interceptList;
  if (!listContainer) return;

  // Clear previous markers
  GODSEYE.markers.intercepts.forEach(m => GODSEYE.map?.removeLayer(m));
  GODSEYE.markers.intercepts = [];
  listContainer.innerHTML = '';

  const curLat = pos.lat || 28.6514;
  const curLng = pos.lng || 77.1907;

  // Sort choke points by distance along trajectory
  const calculatedChokes = GODSEYE.chokePoints.map(cp => {
    const distKm = haversine(curLat, curLng, cp.lat, cp.lng);
    const speedKmh = 42;
    const targetEtaSec = Math.round((distKm / speedKmh) * 3600);
    const probPct = Math.min(99.2, Math.max(78.5, 99 - Math.abs(targetEtaSec - cp.baseEtaSec) * 0.1)).toFixed(1);
    return {
      ...cp,
      distKm: distKm.toFixed(1),
      targetEtaSec,
      targetEtaStr: targetEtaSec < 60 ? `${targetEtaSec}s` : `${Math.floor(targetEtaSec / 60)}m ${targetEtaSec % 60}s`,
      probPct
    };
  }).sort((a, b) => a.targetEtaSec - b.targetEtaSec);

  // Top primary intercept recommendation
  const primary = calculatedChokes[0];
  GODSEYE.primaryChokePoint = primary;
  if (primary) {
    if (GODSEYE.dom.primaryChoke) GODSEYE.dom.primaryChoke.textContent = primary.name;
    if (GODSEYE.dom.chokeEta) GODSEYE.dom.chokeEta.textContent = primary.targetEtaStr;
    if (GODSEYE.dom.chokeUnit) GODSEYE.dom.chokeUnit.textContent = `${primary.unit} (${primary.distKm} km)`;
    if (GODSEYE.dom.chokeProb) GODSEYE.dom.chokeProb.textContent = `${primary.probPct}% OPTIMAL`;
    if (GODSEYE.dom.chokeAction) GODSEYE.dom.chokeAction.textContent = primary.action;
    if (GODSEYE.dom.eta) GODSEYE.dom.eta.textContent = primary.targetEtaStr;
  }

  // Populate list
  calculatedChokes.slice(0, 3).forEach((cp, idx) => {
    const item = document.createElement('div');
    item.className = `ge-intercept-item ${idx === 0 ? 'primary' : ''}`;
    item.innerHTML = `
      <div class="ge-ii-header">
        <span class="ge-ii-name">${idx === 0 ? ' ' : ' '}${cp.name}</span>
        <span class="ge-ii-prob">${cp.probPct}%</span>
      </div>
      <div class="ge-ii-meta">
        <span>ETA: <strong style="color:#00e5ff">${cp.targetEtaStr}</strong> (${cp.distKm}km)</span>
        <span>Unit: <strong style="color:#fbbf24">${cp.unit}</strong></span>
      </div>
    `;

    item.addEventListener('click', () => {
      GODSEYE.primaryChokePoint = cp;
      if (GODSEYE.dom.primaryChoke) GODSEYE.dom.primaryChoke.textContent = cp.name;
      if (GODSEYE.dom.chokeEta) GODSEYE.dom.chokeEta.textContent = cp.targetEtaStr;
      if (GODSEYE.dom.chokeUnit) GODSEYE.dom.chokeUnit.textContent = `${cp.unit} (${cp.distKm} km)`;
      if (GODSEYE.dom.chokeProb) GODSEYE.dom.chokeProb.textContent = `${cp.probPct}% OPTIMAL`;
      if (GODSEYE.dom.chokeAction) GODSEYE.dom.chokeAction.textContent = cp.action;
      listContainer.querySelectorAll('.ge-intercept-item').forEach(it => it.classList.remove('primary'));
      item.classList.add('primary');
      GODSEYE.map?.setView([cp.lat, cp.lng], 16, { animate: true });
      playSound('click');
    });

    listContainer.appendChild(item);

    // Add map marker
    if (GODSEYE.interceptionsEnabled && GODSEYE.map) {
      const icon = L.divIcon({
        className: 'ge-marker-intercept',
        html: `<span></span>`,
        iconSize: [20, 20],
        iconAnchor: [10, 10]
      });
      const marker = L.marker([cp.lat, cp.lng], { icon }).addTo(GODSEYE.map);
      marker.bindPopup(`
        <div style="padding:4px;background:#0a0e17;color:#f87171;font-size:10px;font-weight:800">
           STRATEGIC CHOKEPOINT: ${cp.name}<br>
          <span style="color:#00e5ff;font-size:9px">Target ETA: ${cp.targetEtaStr} · Dist: ${cp.distKm} km</span><br>
          <span style="color:#34d399;font-size:9px">Interceptor: ${cp.unit} · Match: ${cp.probPct}%</span><br>
          <span style="color:#fbbf24;font-size:8px;font-weight:700">Action: ${cp.action}</span>
        </div>
      `);
      marker.on('click', () => {
        GODSEYE.primaryChokePoint = cp;
        if (GODSEYE.dom.primaryChoke) GODSEYE.dom.primaryChoke.textContent = cp.name;
        if (GODSEYE.dom.chokeEta) GODSEYE.dom.chokeEta.textContent = cp.targetEtaStr;
        if (GODSEYE.dom.chokeUnit) GODSEYE.dom.chokeUnit.textContent = `${cp.unit} (${cp.distKm} km)`;
        if (GODSEYE.dom.chokeProb) GODSEYE.dom.chokeProb.textContent = `${cp.probPct}% OPTIMAL`;
        if (GODSEYE.dom.chokeAction) GODSEYE.dom.chokeAction.textContent = cp.action;
        listContainer.querySelectorAll('.ge-intercept-item').forEach(it => it.classList.remove('primary'));
        item.classList.add('primary');
      });
      GODSEYE.markers.intercepts.push(marker);
    }
  });
};

function updateGodsEyePanels(veh, step, stepIdx) {
  const d = GODSEYE.dom;
  if (!d.plate) GODSEYE.cacheDOM();

  if (d.plate) d.plate.textContent = veh.plate;
  if (d.make) d.make.textContent = veh.make;
  if (d.color) d.color.textContent = veh.color;
  if (d.reid) d.reid.textContent = veh.reidHash;
  if (d.status) {
    d.status.textContent = veh.isStolen ? ' STOLEN' : 'TRACKING';
    d.status.className = `ge-data-val ${veh.isStolen ? 'red' : 'green'}`;
  }
  if (d.threat) {
    d.threat.textContent = veh.isStolen ? 'CRITICAL' : 'LOW';
    d.threat.className = `ge-data-val ${veh.isStolen ? 'red' : 'green'}`;
  }
  if (d.corridor) d.corridor.textContent = step.street || veh.corridorName || 'Panchkuian Marg';
  if (d.mapmatch) d.mapmatch.textContent = '99.8% ROAD SNAPPED';

  // Sensor network
  if (d.fixedCount) d.fixedCount.textContent = `${FIXED_CAMERAS.length} NODES`;
  if (d.mobileCount) d.mobileCount.textContent = `${BUS_ROUTES.length} ACTIVE`;
  if (d.activeNode) d.activeNode.textContent = step.cam;

  // Bottom bar
  const vehMarker = STATE.markers.vehicles[veh.id];
  const pos = vehMarker ? vehMarker.getLatLng() : { lat: step.lat, lng: step.lng };

  if (d.lat) d.lat.textContent = `${pos.lat.toFixed(4)}°N`;
  if (d.lng) d.lng.textContent = `${pos.lng.toFixed(4)}°E`;
  if (d.roadName) d.roadName.textContent = step.street || veh.corridorName;
  if (d.sightings) d.sightings.textContent = veh.trajectory.length;
  if (d.conf) d.conf.textContent = `${(step.conf * 100).toFixed(0)}%`;

  if (d.reticleLabel) {
    d.reticleLabel.textContent = veh.isStolen ? ' STOLEN — TARGET LOCK' : `TARGET LOCK · ${veh.plate}`;
  }
}

// ════════════ SMOOTH DELEGATED GLIDE TRACKING (NO JITTER, DEADZONE GUARD) ════════════
GODSEYE.onVehicleGlide = function(lat, lng, bearing, veh) {
  if (!GODSEYE.active) return;

  const d = GODSEYE.dom;

  // 1. Move target marker smoothly
  if (GODSEYE.markers.target) {
    GODSEYE.markers.target.setLatLng([lat, lng]);
  }

  // 2. Update telemetry labels
  if (d.lat) d.lat.textContent = `${lat.toFixed(4)}°N`;
  if (d.lng) d.lng.textContent = `${lng.toFixed(4)}°E`;
  if (d.heading) d.heading.textContent = `${bearing.toFixed(0)}° ${getCardinal(bearing)}`;

  // 3. Dynamic Line-of-Sight Beam
  GODSEYE.updateLOS(lat, lng);

  // 4. Deadzone Panning: only smooth-pan when vehicle drifts outside central 30% view
  if (GODSEYE.map && STATE.autoFollow) {
    const nowMs = Date.now();
    if (nowMs - GODSEYE.lastPanTime > 1800) {
      try {
        const bounds = GODSEYE.map.getBounds();
        const innerBounds = bounds.pad(-0.35); // 35% margin deadzone
        if (!innerBounds.contains([lat, lng])) {
          GODSEYE.lastPanTime = nowMs;
          GODSEYE.map.panTo([lat, lng], { animate: true, duration: 1.2 });
        }
      } catch (e) {}
    }
  }
};

GODSEYE.updateLOS = function(lat, lng) {
  if (!GODSEYE.losEnabled || !GODSEYE.map || !GODSEYE.losBeam) return;

  // Find closest camera node
  let closestCam = null;
  let minDist = Infinity;

  FIXED_CAMERAS.forEach(cam => {
    const d = haversine(lat, lng, cam.lat, cam.lng) * 1000; // in meters
    if (d < minDist) {
      minDist = d;
      closestCam = cam;
    }
  });

  if (closestCam && minDist < 650) {
    GODSEYE.losBeam.setLatLngs([[closestCam.lat, closestCam.lng], [lat, lng]]);
    if (GODSEYE.dom.activeNode) GODSEYE.dom.activeNode.textContent = closestCam.id;
    if (GODSEYE.dom.losStatus) GODSEYE.dom.losStatus.textContent = `DIRECT BEAM (${Math.round(minDist)}m)`;
    if (GODSEYE.dom.losNode) GODSEYE.dom.losNode.textContent = closestCam.id;
  } else {
    GODSEYE.losBeam.setLatLngs([]);
    if (GODSEYE.dom.losStatus) GODSEYE.dom.losStatus.textContent = 'SECTOR HANDOFF';
  }
};

function updateGodsEyeLive() {
  if (!GODSEYE.active) return;

  const veh = VEHICLES.find(v => v.id === STATE.selectedVehicle) || VEHICLES[0];
  const stepIdx = STATE.currentTrajectoryStep[veh.id] || 0;
  const step = veh.trajectory[stepIdx];
  const vehMarker = STATE.markers.vehicles[veh.id];
  const pos = vehMarker ? vehMarker.getLatLng() : { lat: step.lat, lng: step.lng };

  // Update bus positions
  GODSEYE.markers.buses.forEach(({ id, marker }) => {
    const bPos = STATE.busPositions[id];
    if (bPos) marker.setLatLng([bPos.lat, bPos.lng]);
  });

  // Speed oscillation
  const d = GODSEYE.dom;
  if (d.speed) d.speed.textContent = `${(39 + Math.sin(Date.now() / 900) * 6).toFixed(0)} km/h`;

  // Update Interceptions Matrix
  GODSEYE.updateInterceptionMatrix(veh, pos);

  // Add to mini feed
  const feed = d.miniFeed;
  if (feed) {
    const now = new Date();
    const ts = `${now.getHours().toString().padStart(2, '0')}:${now.getMinutes().toString().padStart(2, '0')}:${now.getSeconds().toString().padStart(2, '0')}`;
    const item = document.createElement('div');
    item.className = 'ge-feed-item';
    item.innerHTML = `[${ts}] <span class="ge-fi-node">${step.cam}</span> - <span class="ge-fi-plate">${veh.plate}</span> ${(step.conf * 100).toFixed(0)}%`;
    feed.insertBefore(item, feed.firstChild);
    while (feed.children.length > 8) feed.removeChild(feed.lastChild);
  }
}

// ════════════ DOUBLE-BUFFERED HARDWARE-ACCELERATED RADAR SWEEP ════════════
function buildStaticRadarBuffer(w, h) {
  const buffer = document.createElement('canvas');
  buffer.width = w;
  buffer.height = h;
  const ctx = buffer.getContext('2d');
  const cx = w / 2, cy = h / 2;
  const maxR = Math.min(w, h) * 0.45;

  // Concentric range rings
  const ringLabels = ['0.5 km', '1.0 km', '1.5 km', '2.0 km'];
  [0.25, 0.5, 0.75, 1.0].forEach((pct, idx) => {
    ctx.strokeStyle = `rgba(0,229,255,${0.07 + pct * 0.04})`;
    ctx.lineWidth = 0.6;
    ctx.setLineDash([3, 7]);
    ctx.beginPath();
    ctx.arc(cx, cy, maxR * pct, 0, Math.PI * 2);
    ctx.stroke();
    ctx.setLineDash([]);

    // Range label
    ctx.font = '7px monospace';
    ctx.fillStyle = 'rgba(0,229,255,0.4)';
    ctx.fillText(ringLabels[idx], cx + 4, cy - maxR * pct + 9);
  });

  // Crosshairs
  ctx.strokeStyle = 'rgba(0,229,255,0.12)';
  ctx.lineWidth = 0.5;
  ctx.beginPath();
  ctx.moveTo(cx - maxR * 1.05, cy);
  ctx.lineTo(cx + maxR * 1.05, cy);
  ctx.moveTo(cx, cy - maxR * 1.05);
  ctx.lineTo(cx, cy + maxR * 1.05);
  ctx.stroke();

  // Azimuth ticks
  [0, 45, 90, 135, 180, 225, 270, 315].forEach(deg => {
    const rad = (deg - 90) * Math.PI / 180;
    const r1 = maxR * 0.98;
    const r2 = maxR * 1.03;
    ctx.strokeStyle = 'rgba(0,229,255,0.25)';
    ctx.lineWidth = 0.8;
    ctx.beginPath();
    ctx.moveTo(cx + Math.cos(rad) * r1, cy + Math.sin(rad) * r1);
    ctx.lineTo(cx + Math.cos(rad) * r2, cy + Math.sin(rad) * r2);
    ctx.stroke();
  });

  // Military Corner Brackets
  const bracketLen = 28;
  const bracketOffset = 20;
  ctx.strokeStyle = 'rgba(0,229,255,0.28)';
  ctx.lineWidth = 1.2;

  // Top-left
  ctx.beginPath();
  ctx.moveTo(bracketOffset, bracketOffset + bracketLen);
  ctx.lineTo(bracketOffset, bracketOffset);
  ctx.lineTo(bracketOffset + bracketLen, bracketOffset);
  ctx.stroke();

  // Top-right
  ctx.beginPath();
  ctx.moveTo(w - bracketOffset - bracketLen, bracketOffset);
  ctx.lineTo(w - bracketOffset, bracketOffset);
  ctx.lineTo(w - bracketOffset, bracketOffset + bracketLen);
  ctx.stroke();

  // Bottom-left
  ctx.beginPath();
  ctx.moveTo(bracketOffset, h - bracketOffset - bracketLen);
  ctx.lineTo(bracketOffset, h - bracketOffset);
  ctx.lineTo(bracketOffset + bracketLen, h - bracketOffset);
  ctx.stroke();

  // Bottom-right
  ctx.beginPath();
  ctx.moveTo(w - bracketOffset - bracketLen, h - bracketOffset);
  ctx.lineTo(w - bracketOffset, h - bracketOffset);
  ctx.lineTo(w - bracketOffset, h - bracketOffset - bracketLen);
  ctx.stroke();

  return buffer;
}

function startRadarSweep() {
  const canvas = GODSEYE.dom.radarCanvas || document.getElementById('ge-radar-canvas');
  if (!canvas) return;

  function resizeCanvas() {
    canvas.width = canvas.offsetWidth;
    canvas.height = canvas.offsetHeight;
    GODSEYE.staticRadarCanvas = buildStaticRadarBuffer(canvas.width, canvas.height);
  }
  resizeCanvas();
  window.addEventListener('resize', resizeCanvas);

  GODSEYE.lastRadarTime = performance.now();
  GODSEYE.lastFpsCheck = performance.now();
  GODSEYE.frameCount = 0;

  function drawSweep(timestamp) {
    if (!GODSEYE.active) return;

    // Pause when tab is backgrounded to eliminate CPU usage
    if (document.hidden) {
      GODSEYE.radarAF = requestAnimationFrame(drawSweep);
      return;
    }

    const t0 = performance.now();
    const ctx = canvas.getContext('2d');
    const w = canvas.width, h = canvas.height;
    const cx = w / 2, cy = h / 2;
    const maxR = Math.min(w, h) * 0.45;

    // Measure FPS
    GODSEYE.frameCount++;
    if (timestamp - GODSEYE.lastFpsCheck >= 1000) {
      GODSEYE.measuredFps = Math.round((GODSEYE.frameCount * 1000) / (timestamp - GODSEYE.lastFpsCheck));
      GODSEYE.frameCount = 0;
      GODSEYE.lastFpsCheck = timestamp;
      if (GODSEYE.dom.renderFps) {
        GODSEYE.dom.renderFps.textContent = `${GODSEYE.measuredFps}.0 FPS · ${GODSEYE.renderDurationMs.toFixed(1)}ms`;
      }
    }

    // Delta time for butter-smooth constant rotation
    const dt = Math.min(0.05, (timestamp - GODSEYE.lastRadarTime) / 1000);
    GODSEYE.lastRadarTime = timestamp;
    GODSEYE.radarAngle = (GODSEYE.radarAngle + dt * 0.8) % (Math.PI * 2);

    // 1. Clear frame
    ctx.clearRect(0, 0, w, h);

    // 2. Blit pre-rendered static radar grid in 1 ultra-fast operation
    if (GODSEYE.staticRadarCanvas) {
      ctx.drawImage(GODSEYE.staticRadarCanvas, 0, 0);
    }

    // 3. Dynamic rotating sweep cone
    const sweepWidth = 0.38;
    const grad = ctx.createConicGradient(GODSEYE.radarAngle, cx, cy);
    grad.addColorStop(0, 'transparent');
    grad.addColorStop(0.01, 'rgba(0,229,255,0.09)');
    grad.addColorStop(sweepWidth / (Math.PI * 2), 'rgba(0,229,255,0.025)');
    grad.addColorStop(sweepWidth / (Math.PI * 2) + 0.01, 'transparent');
    grad.addColorStop(1, 'transparent');

    ctx.fillStyle = grad;
    ctx.beginPath();
    ctx.arc(cx, cy, maxR, 0, Math.PI * 2);
    ctx.fill();

    // 4. Sweep leading edge line
    ctx.strokeStyle = 'rgba(0,229,255,0.45)';
    ctx.lineWidth = 1.2;
    ctx.beginPath();
    ctx.moveTo(cx, cy);
    ctx.lineTo(cx + Math.cos(GODSEYE.radarAngle) * maxR, cy + Math.sin(GODSEYE.radarAngle) * maxR);
    ctx.stroke();

    // Calculate render duration
    GODSEYE.renderDurationMs = performance.now() - t0;

    GODSEYE.radarAF = requestAnimationFrame(drawSweep);
  }

  if (GODSEYE.radarAF) cancelAnimationFrame(GODSEYE.radarAF);
  GODSEYE.radarAF = requestAnimationFrame(drawSweep);
}

