// ════════════ ATTACH INTERACTIVE CANVAS LISTENERS ════════════
function attachInteractiveCanvasListeners(canvas) {
  if (canvas._interactiveAttached) return;
  canvas._interactiveAttached = true;

  canvas.addEventListener('mousemove', (e) => {
    const rect = canvas.getBoundingClientRect();
    const scaleX = canvas.width / rect.width;
    const scaleY = canvas.height / rect.height;
    const mx = (e.clientX - rect.left) * scaleX;
    const my = (e.clientY - rect.top) * scaleY;

    let hovered = null;
    if (canvas._interactiveVehicles) {
      for (const v of canvas._interactiveVehicles) {
        const { x, y, w, h } = v.rect;
        if (mx >= x - 6 && mx <= x + w + 6 && my >= y - 18 && my <= y + h + 6) {
          hovered = v;
          break;
        }
      }
    }

    if (hovered !== canvas._hoveredVehicle) {
      canvas._hoveredVehicle = hovered;
      canvas.style.cursor = hovered ? 'crosshair' : 'default';
      // Trigger instant re-render for crisp feedback
      triggerCanvasRepaint(canvas);
    }
  });

  canvas.addEventListener('mouseleave', () => {
    if (canvas._hoveredVehicle) {
      canvas._hoveredVehicle = null;
      canvas.style.cursor = 'default';
      triggerCanvasRepaint(canvas);
    }
  });

  canvas.addEventListener('click', (e) => {
    if (canvas._hoveredVehicle) {
      acquireTargetFromFootage(canvas._hoveredVehicle);
    }
  });
}

function triggerCanvasRepaint(canvas) {
  const veh = VEHICLES.find(v => v.id === STATE.selectedVehicle) || VEHICLES[0];
  if (!veh) return;
  const stepIdx = STATE.currentTrajectoryStep[veh.id] || 0;
  const step = veh.trajectory[stepIdx] || veh.trajectory[0];
  const isBus = canvas.id.includes('bus');
  renderCameraFeed(canvas, step, veh, isBus);
}

