// ════════════ TARGET ACQUISITION BY PLATE ════════════
function trackByPlate(rawPlate) {
  searchAndReconstructTrajectory(rawPlate, { openModal: false });
  return;
  // legacy fallback

  if (!rawPlate || !rawPlate.trim()) return;
  const plate = rawPlate.trim().toUpperCase();

  let found = VEHICLES.find(v => v.plate.replace(/\s+/g, '') === plate.replace(/\s+/g, ''));
  if (found) {
    selectVehicle(found.id);
    playSound('lock');
    const fixedHits = found.trajectory.filter(t => !t.mobile).length;
    const busHits = found.trajectory.filter(t => t.mobile).length;
    showToast(
      'ANPR SIGHTING CHAIN RECONSTRUCTED',
      `Plate ${found.plate}: ${found.trajectory.length} Sightings linked across ${fixedHits} Fixed CCTVs & ${busHits} DTC Mobile Bus cameras. Blind corridor estimated!`
    );
    return;
  }

  // Check Hotlist
  const hotMatch = HOTLIST.find(h => h.plate.replace(/\s+/g, '') === plate.replace(/\s+/g, ''));
  const isStolen = hotMatch ? true : false;
  const newId = `VEH-${Date.now().toString().slice(-4)}`;

  const template = isStolen ? VEHICLES[1] : (VEHICLES[VEHICLES.length % 3] || VEHICLES[0]);
  const newVeh = {
    id: newId,
    plate: plate,
    type: isStolen ? 'SUV' : 'Sedan',
    color: isStolen ? 'Black' : 'White',
    make: isStolen ? 'Toyota Fortuner' : 'Maruti Swift Dzire',
    status: 'tracking',
    isStolen: isStolen,
    reidHash: Math.random().toString(16).substring(2, 10),
    corridorName: template.corridorName,
    trajectory: JSON.parse(JSON.stringify(template.trajectory)),
    roadPath: [...template.roadPath]
  };

  VEHICLES.push(newVeh);
  initVehicleList('gis-vehicle-list');
  selectVehicle(newId);
  playSound('lock');

  showToast(
    isStolen ? 'HOTLIST MATCH: MULTI-NODE ANPR LOCK' : 'ANPR SIGHTING CHAIN RECONSTRUCTED',
    `Plate ${plate}: Found ${newVeh.trajectory.length} interconnected sightings across Delhi CCTV and DTC Bus cameras.`,
    isStolen
  );
}

