// ════════════ POPULATE CAMERA SELECTORS ════════════
function populateCameraSelectors() {
  const selects = [
    document.getElementById('lcm-cam-select'),
    document.getElementById('gis-cam-picker')
  ];

  selects.forEach(sel => {
    if (!sel) return;
    sel.innerHTML = '<option value="auto"> [AUTO] Current Tracking Node</option>';

    const grpFixed = document.createElement('optgroup');
    grpFixed.label = ' Fixed Junction ANPR (12 Nodes)';
    FIXED_CAMERAS.forEach(cam => {
      const opt = document.createElement('option');
      opt.value = cam.id;
      opt.textContent = `${cam.id} — ${cam.name}`;
      grpFixed.appendChild(opt);
    });
    sel.appendChild(grpFixed);

    const grpBus = document.createElement('optgroup');
    grpBus.label = ' Mobile Bus Fleet Cameras (4 Active)';
    BUS_ROUTES.forEach(b => {
      const opt = document.createElement('option');
      opt.value = b.id;
      opt.textContent = `${b.id} — ${b.name}`;
      grpBus.appendChild(opt);
    });
    sel.appendChild(grpBus);

    sel.addEventListener('change', (e) => {
      STATE.liveCamera.activeCamId = e.target.value;
      selects.forEach(s => { if (s && s !== e.target) s.value = e.target.value; });
      playSound('click');
      updateLiveModalDetails();
    });
  });
}

// ════════════ LIVE CAMERA MODAL CONTROLS ════════════
function openLiveCameraModal(camId) {
  const modal = document.getElementById('live-camera-modal');
  if (!modal) return;
  modal.classList.remove('hidden');
  STATE.liveCamera.isOpen = true;

  if (camId) {
    STATE.liveCamera.activeCamId = camId;
    const sel = document.getElementById('lcm-cam-select');
    if (sel) sel.value = camId;
    const gSel = document.getElementById('gis-cam-picker');
    if (gSel) gSel.value = camId;
  }

  updateLiveModalDetails();
  playSound('chirp');

  // Start stream loop
  if (!STATE.liveCamera.rafId) {
    function loop() {
      if (!STATE.liveCamera.isOpen) return;
      renderLiveModalStream();
      STATE.liveCamera.rafId = requestAnimationFrame(loop);
    }
    STATE.liveCamera.rafId = requestAnimationFrame(loop);
  }
}

function closeLiveCameraModal() {
  const modal = document.getElementById('live-camera-modal');
  if (modal) modal.classList.add('hidden');
  STATE.liveCamera.isOpen = false;
  if (STATE.liveCamera.rafId) {
    cancelAnimationFrame(STATE.liveCamera.rafId);
    STATE.liveCamera.rafId = null;
  }
  playSound('click');
}

function updateLiveModalDetails() {
  const veh = VEHICLES.find(v => v.id === STATE.selectedVehicle) || VEHICLES[0];
  const stepIdx = STATE.currentTrajectoryStep[veh?.id] || 0;
  const step = veh?.trajectory[stepIdx] || veh?.trajectory[0];

  let camId = STATE.liveCamera.activeCamId;
  if (camId === 'auto') camId = step?.cam || 'CAM-JNC-04';

  const fixed = FIXED_CAMERAS.find(c => c.id === camId);
  const bus = BUS_ROUTES.find(b => b.id === camId);
  const name = fixed ? fixed.name : bus ? bus.name : 'Karol Bagh Crossing';
  const lat = fixed ? fixed.lat : bus ? bus.waypoints[0].lat : (step?.lat || 28.6514);
  const lng = fixed ? fixed.lng : bus ? bus.waypoints[0].lng : (step?.lng || 77.1907);

  const elName = document.getElementById('lcm-hud-cam-name');
  if (elName) elName.textContent = `${camId} · ${name}`;
  const elGps = document.getElementById('lcm-hud-gps');
  if (elGps) elGps.textContent = `GPS: ${lat.toFixed(4)}° N, ${lng.toFixed(4)}° E`;
  const elLock = document.getElementById('lcm-hud-target-lock');
  if (elLock && veh) elLock.textContent = `TARGET: ${veh.plate} (${veh.color} ${veh.make})`;
}

function renderLiveModalStream() {
  const canvas = document.getElementById('lcm-live-canvas');
  if (!canvas) return;

  const veh = VEHICLES.find(v => v.id === STATE.selectedVehicle) || VEHICLES[0];
  const stepIdx = STATE.currentTrajectoryStep[veh?.id] || 0;
  const step = veh?.trajectory[stepIdx] || veh?.trajectory[0];

  let camId = STATE.liveCamera.activeCamId;
  const isAuto = camId === 'auto';
  if (isAuto) camId = step?.cam || 'CAM-JNC-04';

  const isBus = camId.startsWith('BUS');
  const dummyStep = {
    cam: camId,
    mobile: isBus,
    lat: step?.lat || 28.6514,
    lng: step?.lng || 77.1907,
    conf: step?.conf || 0.94
  };

  renderCameraFeed(canvas, dummyStep, veh, isBus);
}

// ════════════ INITIALIZE SUITE CONTROLS & EVENT WIRING ════════════
function initTargetAcquisitionAndLiveControls() {
  populateCameraSelectors();

  // 1. India Bounds and Delhi Focus Buttons
  document.getElementById('btn-map-fit-india')?.addEventListener('click', fitIndiaBounds);
  document.getElementById('btn-map-fit-delhi')?.addEventListener('click', fitDelhiCorridor);

  // 2. Open Live Camera Modal Buttons
  document.getElementById('btn-open-live-cam')?.addEventListener('click', () => openLiveCameraModal());
  document.getElementById('btn-gis-cam-popout')?.addEventListener('click', () => openLiveCameraModal());
  document.getElementById('btn-open-live-cam-modal-acq')?.addEventListener('click', () => openLiveCameraModal());
  document.getElementById('lcm-btn-close')?.addEventListener('click', closeLiveCameraModal);

  // 3. PTZ Controls in Live Camera Modal
  document.getElementById('lcm-btn-ptz-in')?.addEventListener('click', () => {
    STATE.liveCamera.ptzZoom = Math.min(3.0, STATE.liveCamera.ptzZoom + 0.25);
    playSound('click');
    showToast(' PTZ DIGITAL ZOOM', `Sensor magnification: ${STATE.liveCamera.ptzZoom.toFixed(2)}x`);
  });

  document.getElementById('lcm-btn-ptz-out')?.addEventListener('click', () => {
    STATE.liveCamera.ptzZoom = Math.max(1.0, STATE.liveCamera.ptzZoom - 0.25);
    playSound('click');
    showToast(' PTZ DIGITAL ZOOM', `Sensor magnification: ${STATE.liveCamera.ptzZoom.toFixed(2)}x`);
  });

  document.getElementById('lcm-btn-ptz-reset')?.addEventListener('click', () => {
    STATE.liveCamera.ptzZoom = 1.0;
    playSound('click');
    showToast(' PTZ RESET', 'Sensor magnification reset to 1.0x wide field.');
  });

  document.getElementById('lcm-btn-night')?.addEventListener('click', function() {
    STATE.liveCamera.nightVision = !STATE.liveCamera.nightVision;
    this.classList.toggle('active', STATE.liveCamera.nightVision);
    playSound('click');
  });

  document.getElementById('lcm-btn-ocr')?.addEventListener('click', function() {
    STATE.liveCamera.ocrOverlay = !STATE.liveCamera.ocrOverlay;
    this.classList.toggle('active', STATE.liveCamera.ocrOverlay);
    playSound('click');
  });

  document.getElementById('lcm-btn-audio')?.addEventListener('click', function() {
    STATE.liveCamera.audioMonitoring = !STATE.liveCamera.audioMonitoring;
    this.classList.toggle('active', STATE.liveCamera.audioMonitoring);
    playSound('chirp');
    showToast(' EDGE AUDIO STREAM', STATE.liveCamera.audioMonitoring ? 'Real-time directional acoustic sensor active.' : 'Audio stream muted.');
  });

  // 4. Target Acquisition Tabs
  const acqTabs = document.querySelectorAll('.acq-tab');
  acqTabs.forEach(t => {
    t.addEventListener('click', () => {
      acqTabs.forEach(tb => tb.classList.remove('active'));
      t.classList.add('active');
      const tabKey = t.dataset.acqTab;
      document.querySelectorAll('.acq-content').forEach(c => c.classList.remove('active'));
      const activeContent = document.getElementById(`acq-content-${tabKey}`);
      if (activeContent) activeContent.classList.add('active');
      playSound('click');
    });
  });

  // 5. Target by Plate Input & Quick Chips
  const plateInput = document.getElementById('acq-plate-input');
  const btnTrackPlate = document.getElementById('btn-acq-track-plate');

  btnTrackPlate?.addEventListener('click', () => {
    if (plateInput) trackByPlate(plateInput.value);
  });

  plateInput?.addEventListener('keydown', (e) => {
    if (e.key === 'Enter') trackByPlate(plateInput.value);
  });

  document.querySelectorAll('.acq-chip').forEach(chip => {
    chip.addEventListener('click', () => {
      document.querySelectorAll('.acq-chip').forEach(c => c.classList.remove('active'));
      chip.classList.add('active');
      const pl = chip.dataset.plate;
      if (plateInput) plateInput.value = pl;
      trackByPlate(pl);
    });
  });

  // 6. Target by Physical Features
  document.getElementById('btn-acq-track-features')?.addEventListener('click', () => {
    const type = document.getElementById('acq-feat-type')?.value || 'Sedan';
    const color = document.getElementById('acq-feat-color')?.value || 'White';
    const make = document.getElementById('acq-feat-make')?.value || '';
    const trait = document.getElementById('acq-feat-trait')?.value || '';
    trackByPhysicalFeatures(type, color, make, trait);
  });

  // 7. Footage Mode Selector (Live vs Recorded Archive)
  function setFootageMode(mode) {
    STATE.liveCamera.recordedMode = (mode === 'rec');
    
    // Update Dual Surveillance bar
    document.querySelectorAll('.sps-btn').forEach(b => {
      b.classList.toggle('active', b.dataset.streamMode === mode);
    });
    const spsRec = document.getElementById('surv-rec-controls');
    const spsLive = document.getElementById('surv-live-indicator');
    if (spsRec) spsRec.classList.toggle('hidden', mode !== 'rec');
    if (spsLive) spsLive.classList.toggle('hidden', mode === 'rec');

    // Update Acquisition tab footage buttons
    const btnLive = document.getElementById('btn-footage-mode-live');
    const btnRec = document.getElementById('btn-footage-mode-rec');
    if (btnLive) btnLive.classList.toggle('active', mode === 'live');
    if (btnRec) btnRec.classList.toggle('active', mode === 'rec');

    playSound('click');
    showToast(
      mode === 'rec' ? ' RECORDED ARCHIVE ACTIVE' : '* LIVE BROADCAST ACTIVE',
      mode === 'rec' ? 'Scrub timeline to review recorded footage. Click any car on screen to track!' : 'Real-time CCTV optical feed streaming at 45 FPS.'
    );

    // Refresh current feeds
    const veh = VEHICLES.find(v => v.id === STATE.selectedVehicle) || VEHICLES[0];
    const stepIdx = STATE.currentTrajectoryStep[veh?.id] || 0;
    const step = veh?.trajectory[stepIdx] || veh?.trajectory[0];
    if (step && veh) renderSurveillanceFeeds(step, veh);
  }

  document.getElementById('btn-surv-stream-live')?.addEventListener('click', () => setFootageMode('live'));
  document.getElementById('btn-surv-stream-rec')?.addEventListener('click', () => setFootageMode('rec'));
  document.getElementById('btn-footage-mode-live')?.addEventListener('click', () => setFootageMode('live'));
  document.getElementById('btn-footage-mode-rec')?.addEventListener('click', () => setFootageMode('rec'));

  // Recorded Scrubber Slider
  const scrubber = document.getElementById('surv-rec-scrubber');
  scrubber?.addEventListener('input', (e) => {
    const val = parseFloat(e.target.value) / 100;
    STATE.liveCamera.recordedProgress = val;
    const min = Math.floor(10 + val * 15);
    const sec = Math.floor((val * 60) % 60);
    const tsStr = `ARCHIVE: 2026-09-19 10:${min.toString().padStart(2,'0')}:${sec.toString().padStart(2,'0')} IST`;
    STATE.liveCamera.recordedTimestamp = tsStr;
    const elTs = document.getElementById('surv-rec-timestamp');
    if (elTs) elTs.textContent = tsStr;

    // Repaint feeds with new positions
    const veh = VEHICLES.find(v => v.id === STATE.selectedVehicle) || VEHICLES[0];
    const stepIdx = STATE.currentTrajectoryStep[veh?.id] || 0;
    const step = veh?.trajectory[stepIdx] || veh?.trajectory[0];
    if (step && veh) renderSurveillanceFeeds(step, veh);
  });

  document.getElementById('btn-rec-rewind')?.addEventListener('click', () => {
    if (scrubber) {
      scrubber.value = Math.max(0, parseFloat(scrubber.value) - 10);
      scrubber.dispatchEvent(new Event('input'));
      playSound('click');
    }
  });

  document.getElementById('btn-rec-forward')?.addEventListener('click', () => {
    if (scrubber) {
      scrubber.value = Math.min(100, parseFloat(scrubber.value) + 10);
      scrubber.dispatchEvent(new Event('input'));
      playSound('click');
    }
  });

  document.getElementById('btn-rec-playpause')?.addEventListener('click', function() {
    STATE.liveCamera.isPaused = !STATE.liveCamera.isPaused;
    this.textContent = STATE.liveCamera.isPaused ? ' Play' : ' Pause';
    playSound('click');
  });

  // Arm Crosshair button
  document.getElementById('btn-arm-footage-target')?.addEventListener('click', () => {
    playSound('chirp');
    showToast(' FOOTAGE PICKER ARMED', 'Crosshair cursor active. Click on any moving or parked car in surveillance feed to initiate lock & tracking!');
    const canvases = [
      document.getElementById('surv-canvas-fixed'),
      document.getElementById('surv-canvas-bus'),
      document.getElementById('gis-camera-canvas')
    ];
    canvases.forEach(c => { if (c) c.style.cursor = 'crosshair'; });
  });

  // Escape key closes modal
  document.addEventListener('keydown', (e) => {
    if (e.key === 'Escape' && STATE.liveCamera.isOpen) {
      closeLiveCameraModal();
    }
  });
}

// Wire startup on DOMContentLoaded
document.addEventListener('DOMContentLoaded', () => {
  initTargetAcquisitionAndLiveControls();
});

