function updateODMetricsBanner() {
  const trips = document.getElementById('od-metric-trips');
  const transit = document.getElementById('od-metric-transit');
  const time = document.getElementById('od-metric-time');
  const imbalance = document.getElementById('od-metric-imbalance');

  if (UTA_STATE.activePeak === 'morning') {
    if (trips) trips.textContent = '38,420';
    if (transit) transit.textContent = '46.2%';
    if (time) time.textContent = '34.6 min';
    if (imbalance) imbalance.textContent = '1.82 (High Inbound)';
  } else if (UTA_STATE.activePeak === 'evening') {
    if (trips) trips.textContent = '41,890';
    if (transit) transit.textContent = '48.9%';
    if (time) time.textContent = '38.2 min';
    if (imbalance) imbalance.textContent = '2.14 (High Outbound)';
  } else if (UTA_STATE.activePeak === 'offpeak') {
    if (trips) trips.textContent = '19,250';
    if (transit) transit.textContent = '38.5%';
    if (time) time.textContent = '24.1 min';
    if (imbalance) imbalance.textContent = '1.08 (Balanced)';
  } else {
    // live
    if (trips) trips.textContent = (35000 + Math.floor(Math.random() * 5000)).toLocaleString();
    if (transit) transit.textContent = (44 + Math.random() * 5).toFixed(1) + '%';
    if (time) time.textContent = (32 + Math.random() * 6).toFixed(1) + ' min';
    if (imbalance) imbalance.textContent = '1.74 (Dynamic)';
  }
}

function renderODMatrixTable() {
  const tbody = document.getElementById('od-matrix-tbody');
  if (!tbody) return;

  const peakKey = (UTA_STATE.activePeak === 'live') ? 'morning' : UTA_STATE.activePeak;
  const rawMatrix = UTA_STATE.matrices[peakKey] || UTA_STATE.matrices.morning;

  // If live, add small jitter
  const matrix = rawMatrix.map(row => row.map(cell => {
    if (cell === 0) return 0;
    if (UTA_STATE.activePeak === 'live') {
      return Math.round(cell * (1 + (Math.random() - 0.5) * 0.08));
    }
    return cell;
  }));

  const zoneNames = ['Karol Bagh', 'Connaught Pl', 'ITO / Pragati', 'AIIMS / S.Ext', 'Nehru Place', 'Dhaula Kuan'];
  let html = '';

  for (let r = 0; r < 6; r++) {
    const rowTotal = matrix[r].reduce((a, b) => a + b, 0);
    html += `<tr><th style="background:var(--bg-tertiary);font-weight:700;text-align:left;padding-left:10px">${zoneNames[r]}</th>`;
    for (let c = 0; c < 6; c++) {
      const val = matrix[r][c];
      if (r === c) {
        html += `<td class="od-cell-diag">—</td>`;
      } else {
        let cls = 'od-cell-low';
        if (val > 1500) cls = 'od-cell-high';
        else if (val > 1000) cls = 'od-cell-med';
        html += `<td class="${cls}" data-r="${r}" data-c="${c}" title="Click to view transit modal split">${val.toLocaleString()}</td>`;
      }
    }
    html += `<td style="font-weight:900;color:var(--accent-cyan);background:rgba(0,229,255,0.06)">${rowTotal.toLocaleString()}</td></tr>`;
  }
  tbody.innerHTML = html;

  // Add click listeners to cells
  tbody.querySelectorAll('td[data-r]').forEach(td => {
    td.addEventListener('click', () => {
      const r = parseInt(td.dataset.r);
      const c = parseInt(td.dataset.c);
      const val = parseInt(td.textContent.replace(/,/g, ''));
      const orig = zoneNames[r];
      const dest = zoneNames[c];
      const busPct = Math.round(40 + Math.random() * 20);
      const carPct = Math.round(100 - busPct - 15);
      const twPct = 15;
      showToast(` O-D FLOW: ${orig} - ${dest}`, `Volume: ${val.toLocaleString()} veh/hr · Modal Split: ${busPct}% Bus, ${carPct}% Car, ${twPct}% 2-Wheeler. Avg transit time: ~31 mins.`);
      playSound('chirp');
    });
  });

  // Populate top corridors summary
  const summaryEl = document.getElementById('od-top-corridors');
  if (summaryEl) {
    const pairs = [];
    for (let r = 0; r < 6; r++) {
      for (let c = 0; c < 6; c++) {
        if (r !== c) {
          pairs.push({ from: zoneNames[r], to: zoneNames[c], vol: matrix[r][c] });
        }
      }
    }
    pairs.sort((a, b) => b.vol - a.vol);
    const top4 = pairs.slice(0, 4);

    let sumHtml = '';
    top4.forEach(p => {
      const barPct = Math.min(100, Math.round((p.vol / 2400) * 100));
      sumHtml += `
        <div class="ocs-item">
          <div class="ocs-corridor-name">
            <span>${p.from} - ${p.to}</span>
            <span class="ocs-vol">${p.vol.toLocaleString()} veh/h</span>
          </div>
          <div class="ocs-bar-wrap">
            <div class="ocs-bar-fill" style="width:${barPct}%"></div>
          </div>
          <div class="ocs-split">
            <span>48% Bus · 38% Car · 14% 2-W</span>
            <span class="cyan">Signal Offset: Optimized</span>
          </div>
        </div>
      `;
    });
    summaryEl.innerHTML = sumHtml;
  }
}

function renderCorridorSpeedGrid() {
  const container = document.getElementById('corridor-speed-grid');
  if (!container) return;

  let html = '';
  UTA_STATE.corridors.forEach(c => {
    let meterColor = '#34d399';
    if (c.los === 'los-f') meterColor = '#ef4444';
    else if (c.los === 'los-e') meterColor = '#f97316';
    else if (c.los === 'los-c') meterColor = '#fbbf24';

    html += `
      <div class="corridor-card">
        <div class="cc-header">
          <span class="cc-name">${c.name}</span>
          <span class="cc-los-badge ${c.los}">${c.losText}</span>
        </div>
        <div class="cc-speed-row">
          <span class="cc-speed-val">${c.speed}</span>
          <span class="cc-speed-unit">km/h avg</span>
          <span class="cc-limit">Limit: ${c.limit} km/h</span>
        </div>
        <div class="cc-meter">
          <div class="cc-meter-fill" style="width:${c.pct}%;background:${meterColor}"></div>
        </div>
        <div class="cc-advisory">
          <span> ${c.advisory}</span>
        </div>
      </div>
    `;
  });
  container.innerHTML = html;
}

function drawBRTSCanvas(canvasId) {
  const ids = canvasId ? [canvasId] : ['ps124-brts-canvas', 'ps124-brts-canvas-pane'];
  ids.forEach(id => {
    const canvas = document.getElementById(id);
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    const w = canvas.width;
    const h = canvas.height;

    ctx.fillStyle = '#0b1320';
    ctx.fillRect(0, 0, w, h);

    // Perspective road lines
    ctx.strokeStyle = '#334155';
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.moveTo(w * 0.1, h);
    ctx.lineTo(w * 0.45, h * 0.25);
    ctx.moveTo(w * 0.9, h);
    ctx.lineTo(w * 0.55, h * 0.25);
    ctx.stroke();

    // Yellow BRTS Bus Lane
    ctx.strokeStyle = '#f59e0b';
    ctx.lineWidth = 4;
    ctx.setLineDash([12, 8]);
    ctx.beginPath();
    ctx.moveTo(w * 0.35, h);
    ctx.lineTo(w * 0.48, h * 0.25);
    ctx.stroke();
    ctx.setLineDash([]);

    // Road text
    ctx.font = 'bold 12px Inter, sans-serif';
    ctx.fillStyle = 'rgba(245, 158, 11, 0.4)';
    ctx.fillText('BUS ONLY // BRTS LANE', w * 0.16, h * 0.7);

    // Unauthorized Car in BRTS lane
    const carX = w * 0.22;
    const carY = h * 0.45;
    ctx.fillStyle = '#ef4444';
    ctx.fillRect(carX, carY, 90, 45);

    // Bounding box overlay
    ctx.strokeStyle = '#ef4444';
    ctx.lineWidth = 2;
    ctx.strokeRect(carX - 4, carY - 4, 98, 53);

    // License plate tag
    ctx.fillStyle = 'rgba(3, 7, 18, 0.9)';
    ctx.fillRect(carX - 4, carY - 24, 140, 18);
    ctx.font = 'bold 9px JetBrains Mono, monospace';
    ctx.fillStyle = '#fca5a5';
    ctx.fillText(' VIOLATION: DL 8C AK 9281', carX, carY - 11);
  });
}

function drawPotholeCanvas(canvasId) {
  const canvas = document.getElementById(canvasId);
  if (!canvas) return;
  const ctx = canvas.getContext('2d');
  const w = canvas.width;
  const h = canvas.height;

  ctx.fillStyle = '#0a0f1d';
  ctx.fillRect(0, 0, w, h);

  // Grid
  ctx.strokeStyle = 'rgba(255,255,255,0.06)';
  ctx.lineWidth = 1;
  for (let y = 0; y < h; y += 30) {
    ctx.beginPath(); ctx.moveTo(0, y); ctx.lineTo(w, y); ctx.stroke();
  }

  // Baseline 1.0g line
  ctx.strokeStyle = 'rgba(56, 189, 248, 0.3)';
  ctx.setLineDash([4, 4]);
  ctx.beginPath();
  ctx.moveTo(0, h * 0.65);
  ctx.lineTo(w, h * 0.65);
  ctx.stroke();
  ctx.setLineDash([]);
  ctx.fillStyle = 'rgba(56, 189, 248, 0.6)';
  ctx.font = '8px JetBrains Mono, monospace';
  ctx.fillText('1.0g Gravity Baseline', 8, h * 0.62);

  // Accelerometer wave with 3.8g spike
  ctx.strokeStyle = '#a78bfa';
  ctx.lineWidth = 2;
  ctx.beginPath();
  for (let x = 0; x < w; x += 4) {
    let yVal = h * 0.65 + Math.sin(x * 0.1) * 6 + (Math.random() - 0.5) * 4;
    // Inject spike at x = w * 0.65
    if (x > w * 0.62 && x < w * 0.68) {
      yVal = h * 0.65 - 75 + Math.sin(x * 0.5) * 15;
    }
    if (x === 0) ctx.moveTo(x, yVal);
    else ctx.lineTo(x, yVal);
  }
  ctx.stroke();

  // Spike annotation
  ctx.fillStyle = '#ef4444';
  ctx.beginPath();
  ctx.arc(w * 0.65, h * 0.65 - 75, 5, 0, Math.PI * 2);
  ctx.fill();

  ctx.fillStyle = '#fca5a5';
  ctx.font = 'bold 10px JetBrains Mono, monospace';
  ctx.fillText(' 3.8g VERTICAL SHOCK', w * 0.67, h * 0.65 - 75);
}

function drawAQICanvas(canvasId) {
  const canvas = document.getElementById(canvasId);
  if (!canvas) return;
  const ctx = canvas.getContext('2d');
  const w = canvas.width;
  const h = canvas.height;

  ctx.fillStyle = '#0a0f1d';
  ctx.fillRect(0, 0, w, h);

  // Draw gradient fill line for PM2.5
  const grad = ctx.createLinearGradient(0, 0, 0, h);
  grad.addColorStop(0, 'rgba(52, 211, 153, 0.25)');
  grad.addColorStop(1, 'rgba(52, 211, 153, 0.0)');

  ctx.fillStyle = grad;
  ctx.beginPath();
  ctx.moveTo(0, h);
  for (let x = 0; x <= w; x += 10) {
    const y = h * 0.5 + Math.sin(x * 0.04) * 25 + Math.cos(x * 0.02) * 15;
    ctx.lineTo(x, y);
  }
  ctx.lineTo(w, h);
  ctx.closePath();
  ctx.fill();

  ctx.strokeStyle = '#34d399';
  ctx.lineWidth = 2;
  ctx.beginPath();
  for (let x = 0; x <= w; x += 10) {
    const y = h * 0.5 + Math.sin(x * 0.04) * 25 + Math.cos(x * 0.02) * 15;
    if (x === 0) ctx.moveTo(x, y);
    else ctx.lineTo(x, y);
  }
  ctx.stroke();

  ctx.fillStyle = '#34d399';
  ctx.font = 'bold 9px JetBrains Mono, monospace';
  ctx.fillText('* PMS5003 Laser Particle Counter · Plantower I2C Telemetry', 10, 20);
}


// ========================= IRCTC THEME & ACCESSIBILITY CONTROLLER =========================
function initIRCTCThemeController() {
  const body = document.body;
  const themeBtn = document.getElementById('btn-theme-toggle');
  const themeLabel = document.getElementById('theme-btn-label');

  // Strictly enforce IRCTC Official Theme
  setPortalTheme('irctc');

  if (themeBtn) {
    themeBtn.addEventListener('click', () => {
      setPortalTheme('irctc');
      showToast('THEME: IRCTC OFFICIAL PORTAL', 'Indian Railways Royal Navy and Saffron Orange palette active.');
      playSound('click');
    });
  }

  function setPortalTheme(theme) {
    body.classList.add('theme-irctc');
    body.classList.remove('theme-tactical');
    if (themeLabel) themeLabel.textContent = 'Theme: IRCTC Portal';
    if (themeBtn) themeBtn.title = 'Current: IRCTC Official Government Portal Theme';
    localStorage.setItem('vesper-theme', 'irctc');
  }

  // Accessibility Font Sizers
  let baseFontSize = 14;
  const decBtn = document.getElementById('btn-font-dec');
  const resetBtn = document.getElementById('btn-font-reset');
  const incBtn = document.getElementById('btn-font-inc');

  if (decBtn) {
    decBtn.addEventListener('click', () => {
      baseFontSize = Math.max(12, baseFontSize - 1);
      document.documentElement.style.fontSize = `${baseFontSize}px`;
      decBtn.classList.add('active');
      resetBtn?.classList.remove('active');
      incBtn?.classList.remove('active');
    });
  }
  if (resetBtn) {
    resetBtn.addEventListener('click', () => {
      baseFontSize = 14;
      document.documentElement.style.fontSize = '14px';
      resetBtn.classList.add('active');
      decBtn?.classList.remove('active');
      incBtn?.classList.remove('active');
    });
  }
  if (incBtn) {
    incBtn.addEventListener('click', () => {
      baseFontSize = Math.min(18, baseFontSize + 1);
      document.documentElement.style.fontSize = `${baseFontSize}px`;
      incBtn.classList.add('active');
      decBtn?.classList.remove('active');
      resetBtn?.classList.remove('active');
    });
  }

  // Language Toggle
  const langToggle = document.getElementById('btn-lang-toggle');
  const langEn = document.getElementById('lang-en');
  const langHi = document.getElementById('lang-hi');
  if (langToggle) {
    langToggle.addEventListener('click', () => {
      const isHi = langHi?.classList.contains('active');
      if (isHi) {
        langHi?.classList.remove('active');
        langEn?.classList.add('active');
        showToast(' LANGUAGE SETTING', 'Portal language switched to English');
      } else {
        langEn?.classList.remove('active');
        langHi?.classList.add('active');
        showToast(' भाषा चयन', 'पोर्टल की प्राथमिक भाषा अब हिन्दी (Devanagari) पर सेट है');
      }
      playSound('chirp');
    });
  }
}

// Global bootstrap on DOM ready
document.addEventListener('DOMContentLoaded', () => {
  initIRCTCThemeController();
  initUrbanTrafficAnalytics();
});


// ════════════ GLOBAL MAP & LAYOUT RESIZE OBSERVER ════════════
let _resizeDebounce = null;
const appGlobalResizeObserver = new ResizeObserver(() => {
  if (_resizeDebounce) cancelAnimationFrame(_resizeDebounce);
  _resizeDebounce = requestAnimationFrame(() => {
    STATE.maps.gis?.invalidateSize();
    STATE.maps.surv?.invalidateSize();
    STATE.maps.grid?.invalidateSize();
    if (typeof GODSEYE !== 'undefined' && GODSEYE.active && GODSEYE.map) {
      GODSEYE.map.invalidateSize();
    }
  });
});

window.addEventListener('DOMContentLoaded', () => {
  const container = document.getElementById('windows-container') || document.body;
  appGlobalResizeObserver.observe(container);
});

// Global Escape key listener to close modals or collapse expanded panes
window.addEventListener('keydown', (e) => {
  if (e.key === 'Escape') {
    closeSightingChainModal();
    document.getElementById('modal-certificate')?.classList.add('hidden');
    document.getElementById('modal-api-gateway')?.classList.add('hidden');
    document.getElementById('live-camera-modal')?.classList.add('hidden');
    if (typeof GODSEYE !== 'undefined' && GODSEYE.active) {
      toggleGodsEye();
    }
    collapseExpandedPane();
  }
});
